import os, pty, sys, time, select, fcntl, termios, struct, re, subprocess, signal

def run(cmd, rows=40, cols=200, send='', wait=3.0, env=None, after=0.0, logf=None, cwd=None):
    """Run cmd on a pty. send: list of (delay, bytes) to send. Returns (raw, screen)"""
    pid, fd = pty.fork()
    if pid == 0:
        if cwd: os.chdir(cwd)
        e = dict(os.environ); e['TERM']='xterm-256color'
        if env: e.update(env)
        os.execvpe(cmd[0], cmd, e)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    t0 = time.time()
    out = bytearray()
    sent = False
    end = t0 + wait
    while time.time() < end:
        r,_,_ = select.select([fd],[],[],0.05)
        if r:
            try: b = os.read(fd, 65536)
            except OSError: break
            if not b: break
            out += b
        if not sent and send and time.time() - t0 >= send[0][0]:
            os.write(fd, send[0][1]); send = send[1:]
            if not send: sent = True
    if after:
        out += b'\n@@AFTER@@\n'
        end = time.time()+after
        while time.time() < end:
            r,_,_ = select.select([fd],[],[],0.05)
            if r:
                try: b = os.read(fd, 65536)
                except OSError: break
                if not b: break
                out += b
    try: os.close(fd)
    except: pass
    try: os.waitpid(pid, os.WNOHANG)
    except: pass
    if logf:
        open(logf,'wb').write(bytes(out))
    return bytes(out)
