{"command": "cd /workspace && cat > term.go <<'GOEOF'
package main

import (
	"syscall"
	"unsafe"
)

// Terminal control helpers based on raw ioctl(2) calls.

type winsize struct {
	Row, Col, Xpixel, Ypixel uint16
}

type termState struct {
	saved syscall.Termios
	fd    uintptr
	valid bool
}

func ioctl(fd uintptr, req uintptr, arg uintptr) error {
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, fd, req, arg)
	if e != 0 {
		return e
	}
	return nil
}

// termSize returns terminal size in (rows, cols).
func termSize(fd uintptr) (int, int, bool) {
	var ws winsize
	if err := ioctl(fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws))); err != nil {
		return 0, 0, false
	}
	return int(ws.Row), int(ws.Col), true
}

// makeRaw switches terminal to raw-ish mode used by full screen apps.
func makeRaw(fd uintptr) (*termState, error) {
	var t syscall.Termios
	if err := ioctl(fd, syscall.TCGETS, uintptr(unsafe.Pointer(&t))); err != nil {
		return nil, err
	}
	st := &termState{saved: t, fd: fd, valid: true}
	t.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP |
		syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	t.Oflag &^= syscall.OPOST
	t.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	t.Cflag &^= syscall.CSIZE | syscall.PARENB
	t.Cflag |= syscall.CS8
	t.Cc[syscall.VMIN] = 1
	t.Cc[syscall.VTIME] = 0
	if err := ioctl(fd, syscall.TCSETS, uintptr(unsafe.Pointer(&t))); err != nil {
		return nil, err
	}
	return st, nil
}

func restoreTerm(st *termState) {
	if st == nil || !st.valid {
		return
	}
	t := st.saved
	ioctl(st.fd, syscall.TCSETS, uintptr(unsafe.Pointer(&t)))
}

func isTerminal(fd uintptr) bool {
	var t syscall.Termios
	return ioctl(fd, syscall.TCGETS, uintptr(unsafe.Pointer(&t))) == nil
}
GOEOF
echo ok"}

