cd /workspace && cat > yaml.go <<'GOEOF'
package main

import (
	"strings"
)

// Minimal YAML subset used for gdu configuration files.  Only the subset that
// gdu actually needs is supported: nested block mappings, block sequences and
// plain/quoted scalars.

var yamlSpecialStart = "#,[]{}&*!|>'\"%@`"

func yamlNeedsQuote(s string) bool {
	if s == "" {
		return true
	}
	if strings.ContainsAny(s, "\n\r\t") {
		return true
	}
	if s != strings.TrimSpace(s) {
		return true
	}
	if strings.IndexByte(yamlSpecialStart, s[0]) >= 0 {
		return true
	}
	switch s[0] {
	case '-', '?', ':':
		if len(s) == 1 || s[1] == ' ' {
			return true
		}
	}
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case ':':
			if i == len(s)-1 || s[i+1] == ' ' {
				return true
			}
		case '#':
			if i > 0 && s[i-1] == ' ' {
				return true
			}
		}
	}
	return yamlLooksLikeOtherType(s)
}

func yamlLooksLikeOtherType(s string) bool {
	switch strings.ToLower(s) {
	case "~", "null", "true", "false", "yes", "no", "on", "off", "y", "n":
		return true
	}
	if isYAMLNumber(s) {
		return true
	}
	return false
}

func isYAMLNumber(s string) bool {
	if s == "" {
		return false
	}
	i := 0
	if s[0] == '+' || s[0] == '-' {
		i++
	}
	if i >= len(s) {
		return false
	}
	dots := 0
	for ; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			continue
		}
		if c == '.' {
			dots++
			if dots > 1 {
				return false
			}
			continue
		}
		if i == len(s)-1 && (c == 'e' || c == 'E') {
			return false
		}
		return false
	}
	return true
}

func yamlScalar(s string) string {
	if !yamlNeedsQuote(s) {
		return s
	}
	if strings.ContainsAny(s, "\n\r\t") || strings.Contains(s, "\\") {
		return "\"" + strings.NewReplacer("\\", "\\\\", "\"", "\\\"", "\n", "\\n", "\t", "\\t", "\r", "\\r").Replace(s) + "\""
	}
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func yamlIsCommentOrBlank(line string) bool {
	t := strings.TrimSpace(line)
	return t == "" || strings.HasPrefix(t, "#")
}

type yamlNode struct {
	keys     []string
	values   map[string]string
	children map[string]*yamlNode
	lists    map[string][]string
}

func newYamlNode() *yamlNode {
	return &yamlNode{values: map[string]string{}, children: map[string]*yamlNode{}, lists: map[string][]string{}}
}

func (n *yamlNode) get(path ...string) (string, bool) {
	cur := n
	for i, k := range path {
		if i == len(path)-1 {
			v, ok := cur.values[k]
			return v, ok
		}
		c, ok := cur.children[k]
		if !ok {
			return "", false
		}
		cur = c
	}
	return "", false
}

func (n *yamlNode) getList(path ...string) ([]string, bool) {
	cur := n
	for i, k := range path {
		if i == len(path)-1 {
			v, ok := cur.lists[k]
			return v, ok
		}
		c, ok := cur.children[k]
		if !ok {
			return nil, false
		}
		cur = c
	}
	return nil, false
}

func (n *yamlNode) getBool(path ...string) bool {
	v, ok := n.get(path...)
	if !ok {
		return false
	}
	switch strings.ToLower(strings.TrimSpace(v)) {
	case "true", "yes", "on", "y", "1":
		return true
	}
	return false
}

func (n *yamlNode) getInt(path ...string) int {
	v, ok := n.get(path...)
	if !ok {
		return 0
	}
	v = strings.TrimSpace(v)
	if v == "" {
		return 0
	}
	neg := false
	i := 0
	if v[0] == '-' {
		neg = true
		i = 1
	} else if v[0] == '+' {
		i = 1
	}
	val := 0
	for ; i < len(v); i++ {
		if v[i] < '0' || v[i] > '9' {
			return 0
		}
		val = val*10 + int(v[i]-'0')
	}
	if neg {
		return -val
	}
	return val
}

// parseYAML parses the config subset.
func parseYAML(data string) (*yamlNode, error) {
	root := newYamlNode()
	type frame struct {
		node *yamlNode
		ind  int
	}
	stack := []frame{{root, -1}}
	lines := strings.Split(data, "\n")
	i := 0
	for i < len(lines) {
		raw := lines[i]
		i++
		if yamlIsCommentOrBlank(raw) {
			continue
		}
		ind := 0
		for ind < len(raw) && raw[ind] == ' ' {
			ind++
		}
		body := strings.TrimSpace(raw[ind:])
		if body == "" {
			continue
		}
		for len(stack) > 1 && ind <= stack[len(stack)-1].ind {
			stack = stack[:len(stack)-1]
		}
		parent := stack[len(stack)-1].node
		if strings.HasPrefix(body, "- ") || body == "-" {
			val := strings.TrimSpace(strings.TrimPrefix(body, "-"))
			parent.lists[""] = append(parent.lists[""], unquoteYAML(val))
			continue
		}
		idx := strings.Index(body, ":")
		if idx < 0 {
			continue
		}
		key := strings.TrimSpace(body[:idx])
		rest := strings.TrimSpace(body[idx+1:])
		rest = stripComment(rest)
		if rest == "" {
			child := newYamlNode()
			parent.children[key] = child
			stack = append(stack, frame{child, ind})
			continue
		}
		if rest == "[]" {
			parent.lists[key] = []string{}
			continue
		}
		if strings.HasPrefix(rest, "[") && strings.HasSuffix(rest, "]") {
			inner := strings.TrimSpace(rest[1 : len(rest)-1])
			var items []string
			if inner != "" {
				items = strings.Split(inner, ",")
				for j := range items {
					items[j] = unquoteYAML(strings.TrimSpace(items[j]))
				}
			}
			parent.lists[key] = items
			continue
		}
		parent.values[key] = unquoteYAML(rest)
	}
	return root, nil
}

func stripComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inD {
				inS = !inS
			}
		case '"':
			if !inS {
				inD = !inD
			}
		case '#':
			if !inS && !inD && (i == 0 || s[i-1] == ' ') {
				return strings.TrimSpace(s[:i])
			}
		}
	}
	return s
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if s[0] == '\'' && s[len(s)-1] == '\'' {
			return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
		}
		if s[0] == '"' && s[len(s)-1] == '"' {
			body := s[1 : len(s)-1]
			if !strings.Contains(body, "\\") {
				return body
			}
			var sb strings.Builder
			for i := 0; i < len(body); i++ {
				if body[i] == '\\' && i+1 < len(body) {
					i++
					switch body[i] {
					case 'n':
						sb.WriteByte('\n')
					case 't':
						sb.WriteByte('\t')
					case 'r':
						sb.WriteByte('\r')
					case '\\':
						sb.WriteByte('\\')
					case '"':
						sb.WriteByte('"')
					default:
						sb.WriteByte(body[i])
					}
					continue
				}
				sb.WriteByte(body[i])
			}
			return sb.String()
		}
	}
	return s
}

// writeYAMLValue renders a scalar or list of scalars the way gdu does.
func writeYAMLScalar(out *strings.Builder, ind int, key, val string) {
	pad := strings.Repeat(" ", ind)
	if val == "" {
		out.WriteString(pad + key + ": \"\"\n")
		return
	}
	out.WriteString(pad + key + ": " + yamlScalar(val) + "\n")
}

func writeYAMLList(out *strings.Builder, ind int, key string, vals []string) {
	pad := strings.Repeat(" ", ind)
	if len(vals) == 0 {
		out.WriteString(pad + key + ": []\n")
		return
	}
	out.WriteString(pad + key + ":\n")
	for _, v := range vals {
		out.WriteString(pad + "    - " + yamlScalar(v) + "\n")
	}
}
