	lines := strings.Split(data, "\n")
	i := 0
	for i < len(lines) {
		raw := lines[i]
		i++
		if yamlIsCommentOrBlank(raw) {
			continue
		}
		ind := 0
		for ind < len(raw) && raw[ind] == ' ' {
			ind++
		}
		body := strings.TrimSpace(raw[ind:])
		if body == "" {
			continue
		}
		for len(stack) > 1 && ind <= stack[len(stack)-1].ind {
			stack = stack[:len(stack)-1]
		}
		parent := stack[len(stack)-1].node
		if strings.HasPrefix(body, "- ") || body == "-" {
			val := strings.TrimSpace(strings.TrimPrefix(body, "-"))
			parent.lists[""] = append(parent.lists[""], unquoteYAML(val))
			continue
		}
		idx := strings.Index(body, ":")
		if idx < 0 {
			continue
		}
		key := strings.TrimSpace(body[:idx])
		rest := strings.TrimSpace(body[idx+1:])
		rest = stripComment(rest)
		if rest == "" {
			child := newYamlNode()
			parent.children[key] = child
			stack = append(stack, frame{child, ind})
			continue
		}
		if rest == "[]" {
			parent.lists[key] = []string{}
			continue
		}
		if strings.HasPrefix(rest, "[") && strings.HasSuffix(rest, "]") {
			inner := strings.TrimSpace(rest[1 : len(rest)-1])
			var items []string
			if inner != "" {
				items = strings.Split(inner, ",")
				for j := range items {
					items[j] = unquoteYAML(strings.TrimSpace(items[j]))
				}
			}
			parent.lists[key] = items
			continue
		}
		parent.values[key] = unquoteYAML(rest)
	}
	return root, nil
}

func stripComment(s string) string {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inD {
				inS = !inS
			}
		case '"':
			if !inS {
				inD = !inD
			}
		case '#':
			if !inS && !inD && (i == 0 || s[i-1] == ' ') {
				return strings.TrimSpace(s[:i])
			}
		}
	}
	return s
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if s[0] == '\'' && s[len(s)-1] == '\'' {
			return strings.ReplaceAll(s[1:len(s)-1], "''", "'")
		}
		if s[0] == '"' && s[len(s)-1] == '"' {
			body := s[1 : len(s)-1]
			if !strings.Contains(body, "\\") {
				return body
			}
			var sb strings.Builder
			for i := 0; i < len(body); i++ {
				if body[i] == '\\' && i+1 < len(body) {
					i++
					switch body[i] {
					case 'n':
						sb.WriteByte('\n')
					case 't':
						sb.WriteByte('\t')
					case 'r':
						sb.WriteByte('\r')
					case '\\':
						sb.WriteByte('\\')
					case '"':
						sb.WriteByte('"')
					default:
						sb.WriteByte(body[i])
					}
					continue
				}
				sb.WriteByte(body[i])
			}
			return sb.String()
		}
	}
	return s
}

// writeYAMLValue renders a scalar or list of scalars the way gdu does.
func writeYAMLScalar(out *strings.Builder, ind int, key, val string) {
	pad := strings.Repeat(" ", ind)
	if val == "" {
		out.WriteString(pad + key + ": \"\"\n")
		return
	}
	out.WriteString(pad + key + ": " + yamlScalar(val) + "\n")
}

func writeYAMLList(out *strings.Builder, ind int, key string, vals []string) {
	pad := strings.Repeat(" ", ind)
	if len(vals) == 0 {
		out.WriteString(pad + key + ": []\n")
		return
	}
	out.WriteString(pad + key + ":\n")
	for _, v := range vals {
		out.WriteString(pad + "    - " + yamlScalar(v) + "\n")
	}
}
GOEOF
echo ok"}

