package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Color is a terminal color specification.  Empty string means "default".
type Color string

// Config holds all gdu settings.
type Config struct {
	Style StyleConfig
	SortBy string
	SortOrder string
	LogFile string
	InputFile string
	OutputFile string
	IgnoreFromFile string
	IgnoreDirs []string
	IgnoreDirPatterns []string
	Type []string
	ExcludeType []string
	MaxCores int
	Top int
	Depth int
	SequentialScanning bool
	ShowApparentSize bool
	ShowRelativeSize bool
	ShowAnnexedSize bool
	ShowItemCount bool
	ShowMtime bool
	NoColor bool
	Mouse bool
	NonInteractive bool
	NoProgress bool
	NoUnicode bool
	NoCross bool
	NoHidden bool
	NoDelete bool
	NoSpawnShell bool
	FollowSymlinks bool
	Profiling bool
	ReadFromStorage bool
	DB string
	Summarize bool
	UseSIPrefix bool
	NoPrefix bool
	ShowInKib bool
	ReverseSort bool
	ChangeCWD bool
	DeleteInBackground bool
	DeleteInParallel bool
	Since string
	Until string
	MaxAge string
	MinAge string
	ArchiveBrowsing bool
	CollapsePath bool
	// internal
	ConfigFile string
	WriteConfig bool
	ShowDisks bool
	FollowConfig bool
	Version bool
}

type StyleConfig struct {
	Footer        StyleTriplet
	SelectedRow   StylePair
	ResultRow     StylePair2
	Header        StyleHeader
	ProgressModal struct{ CurrentItemPathMaxLen int }
	UseOldSizeBar bool
}

type StyleTriplet struct {
	TextColor, BackgroundColor, NumberColor string
}

type StylePair struct {
	TextColor, BackgroundColor string
}

type StylePair2 struct {
	NumberColor, DirectoryColor string
}

type StyleHeader struct {
	TextColor, BackgroundColor string
	Hidden bool
}

// DefaultColors holds the built-in style defaults.
var DefaultStyle = StyleConfig{
	Footer:      StyleTriplet{TextColor: "#000000", BackgroundColor: "#2479D0", NumberColor: "#FFFFFF"},
	SelectedRow: StylePair{TextColor: "", BackgroundColor: ""},
	ResultRow:   StylePair2{NumberColor: "#e67100", DirectoryColor: "#3498db"},
	Header:      StyleHeader{TextColor: "#000000", BackgroundColor: "#2479D0", Hidden: false},
}

func defaultConfig() *Config {
	c := &Config{
		Style:     DefaultStyle,
		LogFile:   "/dev/null",
		IgnoreDirs: []string{"/proc", "/dev", "/sys", "/run"},
		MaxCores:  0,
	}
	return c
}

func configPaths() (preferred, secondary string) {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		home = os.Getenv("HOME")
	}
	if home == "" {
		return "", ""
	}
	return filepath.Join(home, ".config", "gdu", "gdu.yaml"), filepath.Join(home, ".gdu.yaml")
}

// LoadConfig reads configuration from file (if any).
func LoadConfig(explicit string) *Config {
	c := defaultConfig()
	path := explicit
	if path == "" {
		a, b := configPaths()
		if a != "" {
			if _, err := os.Stat(a); err == nil {
				path = a
			}
		}
		if path == "" && b != "" {
			if _, err := os.Stat(b); err == nil {
				path = b
			}
		}
	}
	if path == "" {
		return c
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return c
	}
	c.ConfigFile = path
	c.applyYAML(string(data))
	return c
}

func (c *Config) applyYAML(data string) {
	root, err := parseYAML(data)
	if err != nil {
		return
	}
	if v, ok := root.get("style", "footer", "text-color"); ok {
		c.Style.Footer.TextColor = v
	}
	if v, ok := root.get("style", "footer", "background-color"); ok {
		c.Style.Footer.BackgroundColor = v
	}
	if v, ok := root.get("style", "footer", "number-color"); ok {
		c.Style.Footer.NumberColor = v
	}
	if v, ok := root.get("style", "selected-row", "text-color"); ok {
		c.Style.SelectedRow.TextColor = v
	}
	if v, ok := root.get("style", "selected-row", "background-color"); ok {
		c.Style.SelectedRow.BackgroundColor = v
	}
	if v, ok := root.get("style", "result-row", "number-color"); ok {
		c.Style.ResultRow.NumberColor = v
	}
	if v, ok := root.get("style", "result-row", "directory-color"); ok {
		c.Style.ResultRow.DirectoryColor = v
	}
	if v, ok := root.get("style", "header", "text-color"); ok {
		c.Style.Header.TextColor = v
	}
	if v, ok := root.get("style", "header", "background-color"); ok {
		c.Style.Header.BackgroundColor = v
	}
	if _, ok := root.get("style", "header", "hidden"); ok {
		c.Style.Header.Hidden = root.getBool("style", "header", "hidden")
	}
	if _, ok := root.get("style", "progress-modal", "current-item-path-max-len"); ok {
		c.Style.ProgressModal.CurrentItemPathMaxLen = root.getInt("style", "progress-modal", "current-item-path-max-len")
	}
	if _, ok := root.get("style", "use-old-size-bar"); ok {
		c.Style.UseOldSizeBar = root.getBool("style", "use-old-size-bar")
	}
	if v, ok := root.get("sorting", "by"); ok {
		c.SortBy = v
	}
	if v, ok := root.get("sorting", "order"); ok {
		c.SortOrder = v
	}
	str := func(key string, dst *string) {
		if v, ok := root.get(key); ok {
			*dst = v
		}
	}
	str("log-file", &c.LogFile)
	str("input-file", &c.InputFile)
	str("output-file", &c.OutputFile)
	str("ignore-from-file", &c.IgnoreFromFile)
	str("db", &c.DB)
	str("since", &c.Since)
	str("until", &c.Until)
	str("max-age", &c.MaxAge)
	str("min-age", &c.MinAge)
	if v, ok := root.getList("ignore-dirs"); ok {
		c.IgnoreDirs = v
	}
	if v, ok := root.getList("ignore-dir-patterns"); ok {
		c.IgnoreDirPatterns = v
	}
	if v, ok := root.getList("type"); ok {
		c.Type = v
	}
	if v, ok := root.getList("exclude-type"); ok {
		c.ExcludeType = v
	}
	if _, ok := root.get("max-cores"); ok {
		c.MaxCores = root.getInt("max-cores")
	}
	if _, ok := root.get("top"); ok {
		c.Top = root.getInt("top")
	}
	if _, ok := root.get("depth"); ok {
		c.Depth = root.getInt("depth")
	}
	bools := []struct {
		key string
		dst *bool
	}{
		{"sequential-scanning", &c.SequentialScanning},
		{"show-apparent-size", &c.ShowApparentSize},
		{"show-relative-size", &c.ShowRelativeSize},
		{"show-annexed-size", &c.ShowAnnexedSize},
		{"show-item-count", &c.ShowItemCount},
		{"show-mtime", &c.ShowMtime},
		{"no-color", &c.NoColor},
		{"mouse", &c.Mouse},
		{"non-interactive", &c.NonInteractive},
		{"no-progress", &c.NoProgress},
		{"no-unicode", &c.NoUnicode},
		{"no-cross", &c.NoCross},
		{"no-hidden", &c.NoHidden},
		{"no-delete", &c.NoDelete},
		{"no-spawn-shell", &c.NoSpawnShell},
		{"follow-symlinks", &c.FollowSymlinks},
		{"profiling", &c.Profiling},
		{"read-from-storage", &c.ReadFromStorage},
		{"summarize", &c.Summarize},
		{"use-si-prefix", &c.UseSIPrefix},
		{"no-prefix", &c.NoPrefix},
		{"show-in-kib", &c.ShowInKib},
		{"reverse-sort", &c.ReverseSort},
		{"change-cwd", &c.ChangeCWD},
		{"delete-in-background", &c.DeleteInBackground},
		{"delete-in-parallel", &c.DeleteInParallel},
		{"archive-browsing", &c.ArchiveBrowsing},
		{"collapse-path", &c.CollapsePath},
	}
	for _, b := range bools {
		if _, ok := root.get(b.key); ok {
			*b.dst = root.getBool(b.key)
		}
	}
}

// Save writes the configuration to path in gdu's YAML layout.
func (c *Config) Save(path string) error {
	var sb strings.Builder
	s := &sb
	s.WriteString("style:\n")
	s.WriteString("    footer:\n")
	writeYAMLScalar(s, 8, "text-color", c.Style.Footer.TextColor)
	writeYAMLScalar(s, 8, "background-color", c.Style.Footer.BackgroundColor)
	writeYAMLScalar(s, 8, "number-color", c.Style.Footer.NumberColor)
	s.WriteString("    selected-row:\n")
	writeYAMLScalar(s, 8, "text-color", c.Style.SelectedRow.TextColor)
	writeYAMLScalar(s, 8, "background-color", c.Style.SelectedRow.BackgroundColor)
	s.WriteString("    result-row:\n")
	writeYAMLScalar(s, 8, "number-color", c.Style.ResultRow.NumberColor)
	writeYAMLScalar(s, 8, "directory-color", c.Style.ResultRow.DirectoryColor)
	s.WriteString("    header:\n")
	writeYAMLScalar(s, 8, "text-color", c.Style.Header.TextColor)
	writeYAMLScalar(s, 8, "background-color", c.Style.Header.BackgroundColor)
	if c.Style.Header.Hidden {
		s.WriteString("        hidden: true\n")
	} else {
		s.WriteString("        hidden: false\n")
	}
	s.WriteString("    progress-modal:\n")
	s.WriteString(fmt.Sprintf("        current-item-path-max-len: %d\n", c.Style.ProgressModal.CurrentItemPathMaxLen))
	if c.Style.UseOldSizeBar {
		s.WriteString("    use-old-size-bar: true\n")
	} else {
		s.WriteString("    use-old-size-bar: false\n")
	}
	s.WriteString("sorting:\n")
	writeYAMLScalar(s, 4, "by", c.SortBy)
	writeYAMLScalar(s, 4, "order", c.SortOrder)
	writeYAMLScalar(s, 0, "log-file", c.LogFile)
	writeYAMLScalar(s, 0, "input-file", c.InputFile)
	writeYAMLScalar(s, 0, "output-file", c.OutputFile)
	writeYAMLScalar(s, 0, "ignore-from-file", c.IgnoreFromFile)
	writeYAMLList(s, 0, "ignore-dirs", c.IgnoreDirs)
	writeYAMLList(s, 0, "ignore-dir-patterns", c.IgnoreDirPatterns)
	writeYAMLList(s, 0, "type", c.Type)
	writeYAMLList(s, 0, "exclude-type", c.ExcludeType)
	s.WriteString(fmt.Sprintf("max-cores: %d\n", c.MaxCores))
	s.WriteString(fmt.Sprintf("top: %d\n", c.Top))
	s.WriteString(fmt.Sprintf("depth: %d\n", c.Depth))
	writeBool := func(key string, v bool) {
		if v {
			s.WriteString(key + ": true\n")
		} else {
			s.WriteString(key + ": false\n")
		}
	}
	writeBool("sequential-scanning", c.SequentialScanning)
	writeBool("show-apparent-size", c.ShowApparentSize)
	writeBool("show-relative-size", c.ShowRelativeSize)
	writeBool("show-annexed-size", c.ShowAnnexedSize)
	writeBool("show-item-count", c.ShowItemCount)
	writeBool("show-mtime", c.ShowMtime)
	writeBool("no-color", c.NoColor)
	writeBool("mouse", c.Mouse)
	writeBool("non-interactive", c.NonInteractive)
	writeBool("no-progress", c.NoProgress)
	writeBool("no-unicode", c.NoUnicode)
	writeBool("no-cross", c.NoCross)
	writeBool("no-hidden", c.NoHidden)
	writeBool("no-delete", c.NoDelete)
	writeBool("no-spawn-shell", c.NoSpawnShell)
	writeBool("follow-symlinks", c.FollowSymlinks)
	writeBool("profiling", c.Profiling)
	writeBool("read-from-storage", c.ReadFromStorage)
	writeYAMLScalar(s, 0, "db", c.DB)
	writeBool("summarize", c.Summarize)
