	writeBool("no-progress", c.NoProgress)
	writeBool("no-unicode", c.NoUnicode)
	writeBool("no-cross", c.NoCross)
	writeBool("no-hidden", c.NoHidden)
	writeBool("no-delete", c.NoDelete)
	writeBool("no-spawn-shell", c.NoSpawnShell)
	writeBool("follow-symlinks", c.FollowSymlinks)
	writeBool("profiling", c.Profiling)
	writeBool("read-from-storage", c.ReadFromStorage)
	writeYAMLScalar(s, 0, "db", c.DB)
	writeBool("summarize", c.Summarize)
	writeBool("use-si-prefix", c.UseSIPrefix)
	writeBool("no-prefix", c.NoPrefix)
	writeBool("show-in-kib", c.ShowInKib)
	writeBool("reverse-sort", c.ReverseSort)
	writeBool("change-cwd", c.ChangeCWD)
	writeBool("delete-in-background", c.DeleteInBackground)
	writeBool("delete-in-parallel", c.DeleteInParallel)
	writeYAMLScalar(s, 0, "since", c.Since)
	writeYAMLScalar(s, 0, "until", c.Until)
	writeYAMLScalar(s, 0, "max-age", c.MaxAge)
	writeYAMLScalar(s, 0, "min-age", c.MinAge)
