package main

import (
	"fmt"
	"strconv"
	"strings"
)

var binaryUnits = []string{"B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB", "ZiB", "YiB"}
var siUnits = []string{"B", "kB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"}

// SizeOpts controls how sizes are rendered.
type SizeOpts struct {
	SI       bool
	Kib      bool
	NoPrefix bool
}

func (o SizeOpts) units() []string {
	if o.SI {
		return siUnits
	}
	return binaryUnits
}

func (o SizeOpts) base() int64 {
	if o.SI {
		return 1000
	}
	return 1024
}

// HumanSize formats size according to the options.
func HumanSize(size int64, o SizeOpts) string {
	if o.NoPrefix {
		return strconv.FormatInt(size, 10)
	}
	units := o.units()
	base := o.base()
	if o.Kib {
		return fmt.Sprintf("%.1f %s", float64(size)/float64(base), units[1])
	}
	if size < base {
		return fmt.Sprintf("%.0f %s", float64(size), units[0])
	}
	v := float64(size)
	idx := 0
	for v >= float64(base) && idx < len(units)-1 {
		v /= float64(base)
		idx++
	}
	return fmt.Sprintf("%.1f %s", v, units[idx])
}

// splitHumanSize returns the numeric part and the unit part separately.
func splitHumanSize(size int64, o SizeOpts) (string, string) {
	if o.NoPrefix {
		return strconv.FormatInt(size, 10), ""
	}
	units := o.units()
	base := o.base()
	if o.Kib {
		return fmt.Sprintf("%.1f", float64(size)/float64(base)), units[1]
	}
	if size < base {
		return fmt.Sprintf("%.0f", float64(size)), units[0]
	}
	v := float64(size)
	idx := 0
	for v >= float64(base) && idx < len(units)-1 {
		v /= float64(base)
		idx++
	}
	return fmt.Sprintf("%.1f", v), units[idx]
}

// commaInt formats an integer with thousands separators.
func commaInt(v int64) string {
	s := strconv.FormatInt(v, 10)
	neg := strings.HasPrefix(s, "-")
	if neg {
		s = s[1:]
	}
	if len(s) <= 3 {
		if neg {
			return "-" + s
		}
		return s
	}
	var parts []string
	for len(s) > 3 {
		parts = append([]string{s[len(s)-3:]}, parts...)
		s = s[:len(s)-3]
	}
	parts = append([]string{s}, parts...)
	res := strings.Join(parts, ",")
	if neg {
		return "-" + res
	}
	return res
}

// barChars renders a 10-column size bar plus the leading partial block char.
// Returns the full string (11 runes).
func barChars(size, total int64) string {
	const width = 10
	eighths := 0
	if total > 0 && size > 0 {
		pct := int(float64(size) * 100 / float64(total))
		eighths = int(float64(pct) * 0.8)
		if eighths > width*8 {
			eighths = width * 8
		}
	}
	full := eighths / 8
	part := eighths % 8
	var sb strings.Builder
	for i := 0; i < full; i++ {
		sb.WriteRune(0x2588)
	}
	if part > 0 {
		sb.WriteRune(rune(0x2588 - part))
	}
	for i := full + boolToInt(part > 0); i < width; i++ {
		sb.WriteByte(' ')
	}
	sb.WriteRune(0x258F)
	return sb.String()
}

func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

// barCharsOld renders the old ASCII size bar.
func barCharsOld(size, total int64) string {
	const width = 10
	eighths := 0
	if total > 0 && size > 0 {
		pct := int(float64(size) * 100 / float64(total))
		eighths = int(float64(pct) * 0.8)
		if eighths > width*8 {
			eighths = width * 8
		}
	}
	full := eighths / 8
	part := eighths % 8
	var sb strings.Builder
	sb.WriteByte('[')
	for i := 0; i < full; i++ {
		sb.WriteByte('#')
	}
	if part > 0 {
		sb.WriteByte('+')
	}
	for i := full + boolToInt(part > 0); i < width; i++ {
		sb.WriteByte(' ')
	}
	sb.WriteByte(']')
	return sb.String()
}

func rune(c int) rune {
	return rune(c)
}
