{"command": "cd /workspace && cat > analyze.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

// Item is a single entry of the scanned tree.
type Item struct {
	Name     string
	Mtime    int64
	Asize    int64
	Dsize    int64
	Flag     byte
	IsDir    bool
	Children []*Item
	// link tracking
	LinkPath string
	Annex    bool
}

// FullName returns full path of the item.
func (i *Item) FullName(parent string) string {
	if parent == "" {
		return i.Name
	}
	return parent + "/" + i.Name
}

// Count returns number of entries directly inside the directory.
func (i *Item) Count() int {
	if i == nil || !i.IsDir {
		return 0
	}
	return len(i.Children)
}

// ScanOpts holds options that influence the scanning process.
type ScanOpts struct {
	FollowSymlinks    bool
	NoCross           bool
	NoHidden          bool
	IgnoreDirs        map[string]bool
	IgnorePatterns    []*regexp.Regexp
	Types             map[string]bool
	ExcludeTypes      map[string]bool
	MinAge            time.Time
	MaxAge            time.Time
	Since             time.Time
	Until             time.Time
	ShowAnnexedSize   bool
	MaxCores          int
	Sequential        bool
	UseGitIgnore      bool
	CollapsePath      bool
}

// Stats collects progress information.
type Stats struct {
	Items atomic.Int64
	Bytes atomic.Int64
	Start time.Time
}

func (s *Stats) Total() int64 { return s.Items.Load() }

type scanner struct {
	opts    *ScanOpts
	stats   *Stats
	sem     chan struct{}
	dev     map[string]uint64
	linkMtx sync.Mutex
	seen    map[linkKey]bool
	wg      sync.WaitGroup
	logFile *os.File
	mu      sync.Mutex
}

type linkKey struct {
	dev  uint64
	ino  uint64
}

// Scan analyses the directory tree starting at root.
func Scan(root string, o *ScanOpts, stats *Stats) (*Item, error) {
	if stats == nil {
		stats = &Stats{Start: time.Now()}
	}
	s := &scanner{
		opts:  o,
		stats: stats,
		seen:  map[linkKey]bool{},
	}
	maxCores := o.MaxCores
	if maxCores <= 0 {
		maxCores = 1
	}
	if o.Sequential {
		maxCores = 1
	}
	s.sem = make(chan struct{}, maxCores)
	rootDev, err := devOf(root)
	if err != nil {
		return nil, err
	}
	item, e := s.scanItem(root, "", rootDev, true)
	if e != nil {
		return nil, e
	}
	return item, nil
}

func devOf(path string) (uint64, error) {
	var st syscall.Stat_t
	if err := lstat(path, &st); err != nil {
		return 0, err
	}
	return st.Dev, nil
}

func (s *scanner) acquire() { s.sem <- struct{}{} }
func (s *scanner) release() { <-s.sem }

func (s *scanner) scanItem(path, name string, parentDev uint64, isRoot bool) (*Item, error) {
	var st syscall.Stat_t
	if err := lstat(path, &st); err != nil {
		return nil, err
	}
	it := &Item{Name: name}
	it.Mtime = st.Mtim.Sec
	it.Asize = st.Size
	it.Dsize = st.Blocks * 512
	mode := st.Mode
	if (st.Mode & syscall.S_IFMT) == syscall.S_IFDIR {
		mode = st.Mode
		it.IsDir = true
	}
	if isRoot || it.IsDir {
		// handled below
	}
	if isDirMode(st.Mode) {
		it.IsDir = true
	}
	if s.opts.NoCross && !isRoot {
		if st.Dev != parentDev {
			// do not descend
			return it, nil
		}
	}
	if it.IsDir {
		s.scanDirInto(it, path, st.Dev)
	} else if isSymlinkMode(st.Mode) {
		it.Flag = '@'
		if s.opts.FollowSymlinks {
			var tst syscall.Stat_t
			if err := stat(path, &tst); err == nil {
				if isDirMode(tst.Mode) {
					// symlink to directory is not followed
				} else {
					it.Asize = tst.Size
					it.Dsize = tst.Blocks * 512
					it.Flag = '@'
				}
			}
		}
		if s.opts.ShowAnnexedSize {
			maybeAnnex(it, path)
		}
	} else if isRegMode(st.Mode) {
		if s.opts.FollowSymlinks {
			// regular files unaffected
		}
		// hard link detection
		if st.Nlink > 1 {
			key := linkKey{dev: st.Dev, ino: st.Ino}
			s.linkMtx.Lock()
			seen := s.seen[key]
			s.seen[key] = true
			s.linkMtx.Unlock()
			if seen {
				it.Flag = 'H'
				it.Dsize = 0
			}
		}
	} else if isSymlinkMode(st.Mode) {
		it.Flag = '@'
	}
	if s.opts.ShowAnnexedSize && !it.IsDir && it.Flag == '@' {
		maybeAnnex(it, path)
	}
	if ageFiltered(it, s.opts, st.Mtim.Sec, st.Mode) {
		it.Asize = 0
		it.Dsize = 0
	}
	s.stats.Items.Add(1)
	s.stats.Bytes.Add(it.Dsize)
	return it, nil
}

func maybeAnnex(it *Item, path string) {
	target, err := os.Readlink(path)
	if err != nil {
		return
	}
	if !strings.Contains(target, "annex") {
		return
	}
	var st syscall.Stat_t
	if err := stat(target, &st); err == nil {
		it.Asize = st.Size
	}
}

func isDirMode(m uint32) bool   { return (m & syscall.S_IFMT) == syscall.S_IFDIR }
func isSymlinkMode(m uint32) bool { return (m & syscall.S_IFMT) == syscall.S_IFLNK }
func isRegMode(m uint32) bool   { return (m & syscall.S_IFMT) == syscall.S_IFREG }

func ageFiltered(it *Item, o *ScanOpts, mtime int64, mode uint32) bool {
	if it.IsDir {
		return false
	}
	tm := time.Unix(mtime, 0)
	if !o.MinAge.IsZero() && tm.After(o.MinAge) {
		return true
	}
	if !o.MaxAge.IsZero() && tm.Before(o.MaxAge) {
		return true
	}
	if !o.Since.IsZero() && tm.Before(o.Since) {
		return true
	}
	if !o.Until.IsZero() && tm.After(o.Until) {
		return true
	}
	return false
}

func (s *scanner) scanDirInto(it *Item, path string, dev uint64) {
	f, err := os.Open(path)
	if err != nil {
		it.Flag = '!'
		return
	}
	entries, rerr := f.ReadDir(-1)
