				child, err := s.scanItem(childPath, name, dev, false)
				if err != nil {
					s.logErr(childPath, err)
					it.Children[i] = &Item{Name: name, IsDir: true, Flag: '!'}
					subErr.Store(true)
					s.stats.Items.Add(1)
					return
				}
				if child.Flag == '!' || child.Flag == '.' {
					subErr.Store(true)
				}
				it.Children[i] = child
			}()
			continue
		}
		if s.opts.Types != nil || s.opts.ExcludeTypes != nil {
			ext := fileExt(name)
			if s.opts.ExcludeTypes[ext] {
				it.Children[idx] = nil
				continue
			}
			if s.opts.Types != nil && !s.opts.Types[ext] {
				it.Children[idx] = nil
				continue
			}
		}
		i := idx
		wg.Add(1)
		s.acquire()
		go func() {
			defer wg.Done()
			defer s.release()
			child, err := s.scanItem(childPath, name, dev, false)
			if err != nil {
				s.logErr(childPath, err)
				it.Children[i] = nil
				return
			}
			it.Children[i] = child
		}()
	}
	wg.Wait()
	// compact
	out := it.Children[:0]
	for _, c := range it.Children {
		if c != nil {
			out = append(out, c)
		}
	}
	it.Children = out
	if subErr.Load() {
		if it.Flag == 0 {
			it.Flag = '.'
		}
	}
	if len(it.Children) == 0 && it.Flag == 0 {
		it.Flag = 'e'
	}
	// compute sizes
	for _, c := range it.Children {
		it.Dsize += c.Dsize
		it.Asize += c.Asize
		if c.Mtime > it.Mtime {
			it.Mtime = c.Mtime
		}
	}
}

func fileExt(name string) string {
	i := strings.LastIndexByte(name, '.')
	if i < 0 {
		return ""
	}
	return name[i+1:]
}

func (s *scanner) ignored(path, name string, dev uint64) bool {
	if s.opts.IgnoreDirs[path] {
		return true
	}
	for _, re := range s.opts.IgnorePatterns {
		if re.MatchString(path) || re.MatchString(name) {
			return true
		}
	}
	return false
}

func (s *scanner) logErr(path string, err error) {
	if s.logFile == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	fmt.Fprintf(s.logFile, "%s: %v\n", path, err)
}

// SortItems sorts children according to key and order.
func SortItems(items []*Item, key string, asc bool) {
	sort.SliceStable(items, func(i, j int) bool {
		a, b := items[i], items[j]
		var less bool
		switch key {
		case "name":
			less = a.Name < b.Name
		case "itemCount":
			less = a.Count() < b.Count()
		case "mtime":
			less = a.Mtime < b.Mtime
		default:
			sa := a.Dsize
			sb := b.Dsize
			less = sa < sb
		}
		if less {
			return asc
		}
		return !asc
	})
}

// SortBySizeDesc is the default ordering: size desc, name desc.
func SortBySizeDesc(items []*Item, apparent bool) {
	sort.SliceStable(items, func(i, j int) bool {
		a, b := items[i], items[j]
		sa := a.Dsize
		sb := b.Dsize
		if apparent {
			sa = a.Asize
			sb = b.Asize
		}
		if sa != sb {
			return sa > sb
		}
		return a.Name > b.Name
	})
}
