	ansiNumColor = "\x1b[33;1m"
	ansiDirColor = "\x1b[34;1m"
	ansiReset    = "\x1b[0;22m"
)

type printer struct {
	w      io.Writer
	color  bool
	opts   SizeOpts
	showBar bool
	oldBar bool
}

func (p *printer) sizeStr(sz int64) string {
	if !p.color {
		return HumanSize(sz, p.opts)
	}
	num, unit := splitHumanSize(sz, p.opts)
	if unit == "" {
		return ansiNumColor + num + ansiReset
	}
	return ansiNumColor + num + ansiReset + " " + unit
}

func (p *printer) nameStr(it *Item) string {
	n := it.Name
	if it.IsDir {
		n = "/" + n
	}
	if !p.color {
		return n
	}
	if it.IsDir {
		return ansiDirColor + n + ansiReset
	}
	return n
}

// fieldWidths returns the width used for the size column.
func (p *printer) fieldWidth(list bool) int {
	if list {
		if p.color {
			return 20
		}
		return 10
	}
	if p.color {
		return 19
	}
	return 9
}

func (p *printer) pad(s string, list bool) string {
	w := p.fieldWidth(list)
	n := w - len(s)
	min := 0
	if list {
		min = 1
	}
	if n < min {
		n = min
	}
	return strings.Repeat(" ", n)
}

// printItems writes the listing of a directory's children.
func (p *printer) printItems(dir *Item, parent string) {
	items := append([]*Item{}, dir.Children...)
	SortBySizeDesc(items, p.opts.apparent)
	for _, it := range items {
		if it.IsDir && it.Name == ".." {
			continue
		}
		p.printItem(it, parent, true)
	}
}

func (p *printer) printItem(it *Item, parent string, list bool) {
	sz := it.Dsize
	if p.opts.apparent {
		sz = it.Asize
	}
	flag := " "
	if it.Flag != 0 {
		flag = string(it.Flag)
	}
	var sb strings.Builder
	if list {
		sb.WriteString(flag)
	}
	s := p.sizeStr(sz)
	sb.WriteString(p.pad(s, list))
	sb.WriteString(s)
	sb.WriteString(" ")
	sb.WriteString(p.nameStr(it))
	sb.WriteString("\n")
	io.WriteString(p.w, sb.String())
}

// apparent flag lives inside SizeOpts via pointer indirection - we keep a copy.
func (o SizeOpts) apparentFlag() bool { return false }

// sizePrinter is a small helper that knows which size to display.
type sizePrinter struct {
	p        *printer
	apparent bool
}

// PrintTree prints the tree up to depth levels.
func PrintTree(w io.Writer, root *Item, rootPath string, depth int, color bool, opts SizeOpts, apparent bool) {
	p := &printer{w: w, color: color, opts: opts}
	sz := root.Dsize
	if apparent {
		sz = root.Asize
	}
	s := p.sizeStr(sz)
	io.WriteString(w, p.pad(s, false)+s+" "+rootPath+"\n")
	var walk func(it *Item, path string, lvl int)
	walk = func(it *Item, path string, lvl int) {
		if depth > 0 && lvl > depth {
			return
		}
		items := append([]*Item{}, it.Children...)
		SortBySizeDesc(items, apparent)
		for _, c := range items {
