		sz := f.Dsize
		if apparent {
			sz = f.Asize
		}
		s := p.sizeStr(sz)
		io.WriteString(w, p.pad(s, false)+s+" "+f.LinkPath+"\n")
	}
}

// Progress renders the non-interactive progress line.
type Progress struct {
	w        io.Writer
	spinner  int
	lastLen  int
	disabled bool
}

var spinnerFrames = []rune{'⠇', '⠏', '⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧'}

func (pr *Progress) clear() {
	if pr.disabled {
		return
	}
	fmt.Fprint(pr.w, "\r"+strings.Repeat(" ", 100)+"\r")
}

func (pr *Progress) Show(line string) {
	if pr.disabled {
		return
	}
	pr.clear()
	if line != "" {
		fmt.Fprint(pr.w, line)
	}
}

func (pr *Progress) Scan(stats *Stats, opts SizeOpts) {
	if pr.disabled {
		return
	}
	items := stats.Items.Load()
	bytes := stats.Bytes.Load()
	frame := spinnerFrames[pr.spinner%len(spinnerFrames)]
	line := fmt.Sprintf(" %c Scanning... Total items: \x1b[31;1m%s\x1b[0;22m size: \x1b[33;1m%s\x1b[0;22m",
		frame, commaInt(items), HumanSize(bytes, opts))
	pr.Show(line)
	pr.spinner++
}

func (pr *Progress) Calculating(opts SizeOpts) {
	if pr.disabled {
		return
	}
	frame := spinnerFrames[pr.spinner%len(spinnerFrames)]
	pr.Show(fmt.Sprintf(" %c Calculating disk usage...", frame))
}

func (pr *Progress) Done() {
	pr.Show("")
}

// printDisks renders mounted devices table.
func printDisks(w io.Writer, color bool) {
	disks := MountedDisks()
	fmt.Fprintf(w, "%12s%10s%10s%10s%6s %s\n", "Device", "Size", "Used", "Free", "Used%", "Mount point")
	for _, d := range disks {
		pct := 0
		if d.Total > 0 {
			pct = int(d.Used * 100 / d.Total)
		}
		var dev, sz, us, fr, pc string
		dev = d.Device
		sz = HumanSize(d.Total, SizeOpts{})
		us = HumanSize(d.Used, SizeOpts{})
		fr = HumanSize(d.Free, SizeOpts{})
		pc = strconv.Itoa(pct) + "%"
		fmt.Fprintf(w, "%12s%10s%10s%10s%6s %s\n", dev, sz, us, fr, pc, d.MountPoint)
	}
}

// formatMtime renders mtime column value.
func formatMtime(m int64) string {
	return time.Unix(m, 0).Format("2006-01-02 15:04:05")
}

// baseName returns the display name of the scanned root.
func baseName(p string) string {
	return filepath.Base(p)
}
GOEOF
echo ok"}

