		sz = it.Asize
	}
	flag := " "
	if it.Flag != 0 {
		flag = string(it.Flag)
	}
	var sb strings.Builder
	if list {
		sb.WriteString(flag)
	}
	s := p.sizeStr(sz)
	sb.WriteString(p.pad(s, list))
	sb.WriteString(s)
	sb.WriteString(" ")
	sb.WriteString(p.nameStr(it))
	sb.WriteString("\n")
	io.WriteString(p.w, sb.String())
}

// apparent flag lives inside SizeOpts via pointer indirection - we keep a copy.
func (o SizeOpts) apparentFlag() bool { return false }

// sizePrinter is a small helper that knows which size to display.
type sizePrinter struct {
	p        *printer
	apparent bool
}

// PrintTree prints the tree up to depth levels.
func PrintTree(w io.Writer, root *Item, rootPath string, depth int, color bool, opts SizeOpts, apparent bool) {
	p := &printer{w: w, color: color, opts: opts}
	sz := root.Dsize
	if apparent {
		sz = root.Asize
	}
	s := p.sizeStr(sz)
	io.WriteString(w, p.pad(s, false)+s+" "+rootPath+"\n")
	var walk func(it *Item, path string, lvl int)
	walk = func(it *Item, path string, lvl int) {
		if depth > 0 && lvl > depth {
			return
		}
		items := append([]*Item{}, it.Children...)
		SortBySizeDesc(items, apparent)
		for _, c := range items {
			if c.IsDir && c.Name == ".." {
				continue
			}
			csz := c.Dsize
			if apparent {
				csz = c.Asize
			}
			cs := p.sizeStr(csz)
			io.WriteString(w, p.pad(cs, false)+cs+" "+path+"/"+c.Name+"\n")
			if c.IsDir {
				walk(c, path+"/"+c.Name, lvl+1)
			}
		}
	}
	if depth != 1 {
		walk(root, rootPath, 1)
	}
}

// PrintTop prints the top N largest files.
func PrintTop(w io.Writer, root *Item, rootPath string, n int, color bool, opts SizeOpts, apparent bool) {
	p := &printer{w: w, color: color, opts: opts}
	var files []*Item
	var walk func(it *Item, path string)
	walk = func(it *Item, path string) {
		for _, c := range it.Children {
			if c.IsDir && c.Name == ".." {
				continue
			}
			if c.IsDir {
				walk(c, path+"/"+c.Name)
				continue
			}
			files = append(files, c)
			c.LinkPath = path + "/" + c.Name
		}
	}
	walk(root, rootPath)
	sort.SliceStable(files, func(i, j int) bool {
		a, b := files[i], files[j]
		sa, sb := a.Dsize, b.Dsize
		if apparent {
			sa, sb = a.Asize, b.Asize
		}
		if sa != sb {
			return sa > sb
		}
		return a.Name > b.Name
	})
	if n > len(files) {
		n = len(files)
	}
	for _, f := range files[:n] {
		sz := f.Dsize
		if apparent {
			sz = f.Asize
		}
		s := p.sizeStr(sz)
		io.WriteString(w, p.pad(s, false)+s+" "+f.LinkPath+"\n")
	}
}

// Progress renders the non-interactive progress line.
type Progress struct {
	w        io.Writer
	spinner  int
	lastLen  int
	disabled bool
}

var spinnerFrames = []rune{'⠇', '⠏', '⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧'}

func (pr *Progress) clear() {
	if pr.disabled {
		return
	}
	fmt.Fprint(pr.w, "\r"+strings.Repeat(" ", 100)+"\r")
}

func (pr *Progress) Show(line string) {
	if pr.disabled {
		return
	}
	pr.clear()
	if line != "" {
		fmt.Fprint(pr.w, line)
	}
}

func (pr *Progress) Scan(stats *Stats, opts SizeOpts) {
	if pr.disabled {
		return
	}
	items := stats.Items.Load()
	bytes := stats.Bytes.Load()
	frame := spinnerFrames[pr.spinner%len(spinnerFrames)]
	line := fmt.Sprintf(" %c Scanning... Total items: \x1b[31;1m%s\x1b[0;22m size: \x1b[33;1m%s\x1b[0;22m",
		frame, commaInt(items), HumanSize(bytes, opts))
	pr.Show(line)
	pr.spinner++
}

func (pr *Progress) Calculating(opts SizeOpts) {
	if pr.disabled {
		return
	}
	frame := spinnerFrames[pr.spinner%len(spinnerFrames)]
	pr.Show(fmt.Sprintf(" %c Calculating disk usage...", frame))
}

func (pr *Progress) Done() {
	pr.Show("")
}

// printDisks renders mounted devices table.
func printDisks(w io.Writer, color bool) {
	disks := MountedDisks()
	fmt.Fprintf(w, "%12s%10s%10s%10s%6s %s\n", "Device", "Size", "Used", "Free", "Used%", "Mount point")
	for _, d := range disks {
		pct := 0
		if d.Total > 0 {
			pct = int(d.Used * 100 / d.Total)
		}
		var dev, sz, us, fr, pc string
		dev = d.Device
		sz = HumanSize(d.Total, SizeOpts{})
		us = HumanSize(d.Used, SizeOpts{})
		fr = HumanSize(d.Free, SizeOpts{})
		pc = strconv.Itoa(pct) + "%"
		fmt.Fprintf(w, "%12s%10s%10s%10s%6s %s\n", dev, sz, us, fr, pc, d.MountPoint)
	}
}

// formatMtime renders mtime column value.
func formatMtime(m int64) string {
	return time.Unix(m, 0).Format("2006-01-02 15:04:05")
}

// baseName returns the display name of the scanned root.
func baseName(p string) string {
	return filepath.Base(p)
}
GOEOF
echo ok"}

