package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"strings"
	"time"
)

// jsonItem mirrors the ncdu 1.x JSON item object.
type jsonItem struct {
	Name   string `json:"name"`
	Asize  int64  `json:"asize,omitempty"`
	Dsize  int64  `json:"dsize,omitempty"`
	Mtime  int64  `json:"mtime,omitempty"`
	Ino    uint64 `json:"ino,omitempty"`
	Hlnkc  bool   `json:"hlnkc,omitempty"`
	Notreg bool   `json:"notreg,omitempty"`
}

type jsonInfo struct {
	Progname string `json:"progname"`
	Progver  string `json:"progver"`
	Timestamp int64 `json:"timestamp"`
}

// exportJSON writes the tree in ncdu 1.x compatible format.
func exportJSON(path string, root *Item, ts int64) error {
	var sb strings.Builder
	info, _ := json.Marshal(&jsonInfo{Progname: "gdu", Progver: versionString(), Timestamp: ts})
	sb.WriteString("[1,2,")
	sb.Write(info)
	sb.WriteString(",\n")
	writeJSONDir(&sb, root)
	sb.WriteString("]\n")
	return os.WriteFile(path, []byte(sb.String()), 0644)
}

func writeJSONObj(sb *strings.Builder, it *Item) {
	sb.WriteString(`{"name":`)
	sb.WriteString(jsonQuote(it.Name))
	if it.Asize != 0 {
		sb.WriteString(fmt.Sprintf(",\"asize\":%d", it.Asize))
	}
	if it.Dsize != 0 {
		sb.WriteString(fmt.Sprintf(",\"dsize\":%d", it.Dsize))
	}
	sb.WriteString(fmt.Sprintf(",\"mtime\":%d", it.Mtime))
	if it.Flag == 'H' && it.InoVal != 0 {
		sb.WriteString(fmt.Sprintf(",\"ino\":%d", it.InoVal))
		sb.WriteString(",\"hlnkc\":true")
	}
	if it.Flag == '@' {
		sb.WriteString(",\"notreg\":true")
	}
	sb.WriteString("}")
}

func writeJSONDir(sb *strings.Builder, d *Item) {
	sb.WriteString("[")
	writeJSONObj(sb, d)
	if len(d.Children) == 0 {
		sb.WriteString("\n")
	} else {
		sb.WriteString(",\n")
	}
	for i, c := range d.Children {
		if c.IsDir {
			writeJSONDir(sb, c)
		} else {
			writeJSONObj(sb, c)
		}
		if i < len(d.Children)-1 {
			sb.WriteString(",\n")
		}
	}
	sb.WriteString("]")
}

// importJSON reads ncdu 1.x JSON file into a tree.
func importJSON(path string) (*Item, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("opening input file: %v", err)
	}
	var raw []json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}
	if len(raw) < 4 {
		return nil, errors.New("invalid input file")
	}
	var magic [2]int
	if err := json.Unmarshal(raw[0], &magic[0]); err != nil {
		return nil, err
	}
	if err := json.Unmarshal(raw[1], &magic[1]); err != nil {
		return nil, err
	}
	if magic[0] != 1 || magic[1] != 2 {
		return nil, errors.New("unsupported input file version")
	}
	var info jsonInfo
	if err := json.Unmarshal(raw[2], &info); err != nil {
		return nil, err
	}
	var top []json.RawMessage
	if err := json.Unmarshal(raw[3], &top); err != nil {
		return nil, err
	}
	if len(top) == 0 {
		return nil, errors.New("invalid input file")
	}
	root, err := parseJSONItem(top[0])
	if err != nil {
		return nil, err
	}
	return root, nil
}

func parseJSONItem(raw json.RawMessage) (*Item, error) {
	var arr []json.RawMessage
	if err := json.Unmarshal(raw, &arr); err == nil {
		// directory
		if len(arr) == 0 {
			return nil, errors.New("invalid directory entry")
		}
		var obj jsonItem
		if err := json.Unmarshal(arr[0], &obj); err != nil {
			return nil, err
		}
		d := &Item{Name: obj.Name, Mtime: obj.Mtime, IsDir: true}
		if len(d.Children) == 0 {
			d.Flag = 'e'
		}
		for _, c := range arr[1:] {
			child, err := parseJSONItem(c)
			if err != nil {
				return nil, err
			}
			d.Children = append(d.Children, child)
		}
		if len(d.Children) == 0 {
			d.Flag = 'e'
		} else {
			d.Flag = 0
		}
		recompute(d)
		return d, nil
	}
	var obj jsonItem
	if err := json.Unmarshal(raw, &obj); err != nil {
		return nil, err
	}
	it := &Item{Name: obj.Name, Asize: obj.Asize, Dsize: obj.Dsize, Mtime: obj.Mtime, InoVal: obj.Ino}
	if obj.Notreg {
		it.Flag = '@'
	}
	if obj.Hlnkc {
		it.Flag = 'H'
	}
	return it, nil
}

// recompute computes directory sizes and deduplicates hard links.
func recompute(d *Item) {
	d.Dsize = 0
	d.Asize = 0
	mt := d.Mtime
	seen := map[uint64]bool{}
	if d.InoVal != 0 {
		seen[d.InoVal] = true
	}
	for _, c := range d.Children {
		if c.InoVal != 0 && c.Flag == 'H' {
			if seen[c.InoVal] {
				// already counted
			} else {
				seen[c.InoVal] = true
				d.Dsize += c.Dsize
				d.Asize += c.Asize
			}
		} else {
			d.Dsize += c.Dsize
			d.Asize += c.Asize
		}
		if c.Mtime > mt {
			mt = c.Mtime
		}
	}
	d.Mtime = mt
}

// versionString returns gdu version.
func versionString() string {
	return appVersion
}

// ScanTime returns unix timestamp used in exports.
func ScanTime(t time.Time) int64 {
	return t.Unix()
}
