		}
		for _, c := range arr[1:] {
			child, err := parseJSONItem(c)
			if err != nil {
				return nil, err
			}
			d.Children = append(d.Children, child)
		}
		if len(d.Children) == 0 {
			d.Flag = 'e'
		} else {
			d.Flag = 0
		}
		recompute(d)
		return d, nil
	}
	var obj jsonItem
	if err := json.Unmarshal(raw, &obj); err != nil {
		return nil, err
	}
	it := &Item{Name: obj.Name, Asize: obj.Asize, Dsize: obj.Dsize, Mtime: obj.Mtime, InoVal: obj.Ino}
	if obj.Notreg {
		it.Flag = '@'
	}
	if obj.Hlnkc {
		it.Flag = 'H'
	}
	return it, nil
}

// recompute computes directory sizes and deduplicates hard links.
func recompute(d *Item) {
	d.Dsize = 0
	d.Asize = 0
	mt := d.Mtime
	seen := map[uint64]bool{}
	if d.InoVal != 0 {
		seen[d.InoVal] = true
	}
	for _, c := range d.Children {
		if c.InoVal != 0 && c.Flag == 'H' {
			if seen[c.InoVal] {
				// already counted
			} else {
				seen[c.InoVal] = true
				d.Dsize += c.Dsize
				d.Asize += c.Asize
			}
		} else {
			d.Dsize += c.Dsize
			d.Asize += c.Asize
		}
		if c.Mtime > mt {
			mt = c.Mtime
		}
	}
	d.Mtime = mt
}

// versionString returns gdu version.
func versionString() string {
	return appVersion
}

// ScanTime returns unix timestamp used in exports.
func ScanTime(t time.Time) int64 {
	return t.Unix()
}
GOEOF
echo ok"}

