package main

import (
	"os"
	"strings"
	"syscall"
)

// DiskInfo describes a mounted filesystem.
type DiskInfo struct {
	Device     string
	MountPoint string
	FsType     string
	Total      int64
	Used       int64
	Free       int64
	UsedPct    int
}

var excludedFsTypes = map[string]bool{
	"proc": true, "procfs": true, "linprocfs": true, "tmpfs": true, "devtmpfs": true,
	"devpts": true, "sysfs": true, "linsysfs": true, "cgroup": true, "cgroupfs": true,
	"cgroup2": true, "mqueue": true, "shm": true, "ramfs": true, "squashfs": true,
	"autofs": true, "binfmt_misc": true, "debugfs": true, "tracefs": true, "fusectl": true,
	"configfs": true, "hugetlbfs": true, "pstore": true, "bpf": true, "securityfs": true,
	"nsfs": true, "efivarfs": true, "overlay": true, "overlay2": true, "none": true,
	"udev": true, "devfs": true, "fdescfs": true, "unionfs": true, "autodetect": true,
	"swap": true, "iso9660": true, "dev": true, "run": true, "ramdisk": true,
	"reiserfs": true, "procfs": true, "mfs": true, "ufs": true, "nullfs": true,
	"cd9660": true, "msdosfs": true, "ntfs-3g": true, "zfs": false,
}

// MountedDisks returns list of interesting mounts.
func MountedDisks() []DiskInfo {
	data, err := os.ReadFile("/proc/mounts")
	if err != nil {
		return nil
	}
	var out []DiskInfo
	for _, line := range strings.Split(string(data), "\n") {
		f := strings.Fields(line)
		if len(f) < 4 {
			continue
		}
		dev, mp, fstype := f[0], unescapeMount(f[1]), f[2]
		if excludedFsTypes[fstype] {
			continue
		}
		if dev == "" || mp == "" {
			continue
		}
		var st syscall.Statfs_t
		if err := syscall.Statfs(mp, &st); err != nil {
			continue
		}
		bsize := int64(st.Bsize)
		total := int64(st.Blocks) * bsize
		free := int64(st.Bavail) * bsize
		if free == 0 {
			free = int64(st.Bfree) * bsize
		}
		used := total - free
		pct := 0
		if total > 0 {
			pct = int(used * 100 / total)
		}
		out = append(out, DiskInfo{
			Device: dev, MountPoint: mp, FsType: fstype,
			Total: total, Used: used, Free: free, UsedPct: pct,
		})
	}
	return out
}

func unescapeMount(s string) string {
	s = strings.ReplaceAll(s, "\\040", " ")
	s = strings.ReplaceAll(s, "\\011", "\t")
	s = strings.ReplaceAll(s, "\\012", "\n")
	s = strings.ReplaceAll(s, "\\134", "\\")
	return s
}
GOEOF
