import os, pty, time, select, fcntl, termios, struct, sys, signal, re

def run(cmd, rows=30, cols=100, dur=3.0, cwd=None, keys=(), keydelay=1.0, env=None, respond=True):
    master, slave = os.openpty()
    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.setsid()
        fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
        fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
        os.dup2(slave, 0); os.dup2(slave, 1); os.dup2(slave, 2)
        if slave > 2: os.close(slave)
        if cwd: os.chdir(cwd)
        e=dict(os.environ); e['TERM']='screen'
        if env: e.update(env)
        os.execvpe(cmd[0], cmd, e)
    os.close(slave)
    fcntl.ioctl(master, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    fcntl.fcntl(master, fcntl.F_SETFL, os.O_NONBLOCK)
    t0=time.time(); out=bytearray(); ki=0; nextk=t0+keydelay
    buf=b''
    while time.time()-t0<dur:
        r,_,_=select.select([master],[],[],0.02)
        if r:
            try: b=os.read(master,65536)
            except (OSError,BlockingIOError): b=b''
            if b:
                out+=b
                buf += b
                if respond:
                    # respond to device attributes / cursor position queries
                    if b'\x1b[c' in buf or b'\x1b[0c' in buf:
                        try: os.write(master, b'\x1b[?1;2c')
                        except Exception: pass
                        buf=b''
                    if b'\x1b[6n' in buf:
                        try: os.write(master, b'\x1b[1;1R')
                        except Exception: pass
                        buf=b''
                    if b'\x1bP+q' in buf or b'\x1bP>' in buf:
                        try: os.write(master, b'\x1b\\')
                        except Exception: pass
                        buf=b''
                    if len(buf) > 4096: buf=buf[-64:]
        if ki < len(keys) and time.time()-t0>=keydelay*(ki+1):
            os.write(master, keys[ki]); ki+=1
    try: os.kill(pid, signal.SIGKILL)
    except Exception: pass
    os.waitpid(pid, os.WNOHANG)
    os.close(master)
    return bytes(out)
