import sys, os, pty, time, select, fcntl, termios, struct, signal
sys.path.insert(0,'/tmp')
from screen import render
def frames(cmd, rows, cols, dur=0.6, cwd=None):
    master, slave = os.openpty()
    pid = os.fork()
    if pid == 0:
        os.close(master); os.setsid(); fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
        os.dup2(slave,0); os.dup2(slave,1); os.dup2(slave,2)
        if slave>2: os.close(slave)
        if cwd: os.chdir(cwd)
        e=dict(os.environ); e['TERM']='screen'
        os.execvpe(cmd[0], cmd, e)
    os.close(slave)
    fcntl.ioctl(master, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    t0=time.time(); data=b''; res=[]
    while time.time()-t0<dur:
        r,_,_=select.select([master],[],[],0.02)
        if r:
            try: b=os.read(master,65536)
            except (OSError,BlockingIOError): break
            if not b: break
            data+=b
            res.append((time.time()-t0, bytes(data)))
    try: os.kill(pid, signal.SIGKILL)
    except Exception: pass
    os.waitpid(pid, os.WNOHANG)
    return res
