{"command": "cd /workspace && cat > style.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

// ColorKind describes how a color is specified.
type ColorKind int

const (
	ColorDefault ColorKind = iota
	ColorANSI              // 0..15
	ColorIdx               // 256 palette
	ColorRGB
)

// ColorSpec holds a resolved color.
type ColorSpec struct {
	Kind    ColorKind
	Idx     int
	R, G, B int
}

var colorDefault = ColorSpec{}

// ParseColor parses a color spec string ("#RRGGBB", "red", "1", ...).
func ParseColor(s string) ColorSpec {
	s = strings.TrimSpace(s)
	if s == "" {
		return colorDefault
	}
	if strings.HasPrefix(s, "#") {
		hex := s[1:]
		if len(hex) == 3 {
			hex = string([]byte{hex[0], hex[0], hex[1], hex[1], hex[2], hex[2]})
		}
		if len(hex) == 6 {
			r, e1 := strconv.ParseUint(hex[0:2], 16, 32)
			g, e2 := strconv.ParseUint(hex[2:4], 16, 32)
			b, e3 := strconv.ParseUint(hex[4:6], 16, 32)
			if e1 == nil && e2 == nil && e3 == nil {
				return ColorSpec{Kind: ColorRGB, R: int(r), G: int(g), B: int(b)}
			}
		}
		return colorDefault
	}
	low := strings.ToLower(s)
	if n, ok := colorNames[low]; ok {
		return ColorSpec{Kind: ColorANSI, Idx: n}
	}
	if n, e := strconv.Atoi(s); e == nil {
		if n >= 0 && n < 256 {
			if n < 16 {
				return ColorSpec{Kind: ColorANSI, Idx: n}
			}
			return ColorSpec{Kind: ColorIdx, Idx: n}
		}
	}
	return colorDefault
}

var colorNames = map[string]int{
	"black": 0, "maroon": 1, "red": 1, "green": 2, "lime": 10, "olive": 3,
	"yellow": 3, "navy": 4, "blue": 4, "purple": 5, "fuchsia": 13, "magenta": 5,
	"teal": 6, "aqua": 14, "cyan": 6, "silver": 7, "gray": 8, "grey": 8,
	"white": 15, "brightblack": 8, "brightred": 9, "brightgreen": 10,
	"brightyellow": 11, "brightblue": 12, "brightmagenta": 13, "brightcyan": 14,
	"brightwhite": 15, "lightgray": 7, "lightgrey": 7, "darkgray": 8, "darkgrey": 8,
}

// colorDepth returns supported color count.
func colorDepth() int {
	ct := strings.ToLower(os.Getenv("COLORTERM"))
	if ct == "truecolor" || ct == "24bit" || ct == "yes" {
		return 24
	}
	term := os.Getenv("TERM")
	if strings.Contains(term, "direct") || strings.Contains(term, "truecolor") {
		return 24
	}
	if strings.Contains(term, "256color") {
		return 256
	}
	return 16
}

var cubeLevels = [6]int{0, 95, 135, 175, 215, 255}

// ansiIndex maps an RGB color to the best matching ANSI 16-color code index.
func ansiIndex(c ColorSpec) int {
	// distance in a weighted RGB space against the 16 ANSI colors
	best := 0
	bestD := -1
	pal := ansiPalette
	for i, p := range pal {
		dr := c.R - p[0]
		dg := c.G - p[1]
		db := c.B - p[2]
		d := 2*dr*dr + 4*dg*dg + 3*db*db
		if bestD < 0 || d < bestD {
			bestD = d
			best = i
		}
	}
	return best
}

var ansiPalette = [16][3]int{
	{0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {128, 128, 0},
	{0, 0, 128}, {128, 0, 128}, {0, 128, 128}, {192, 192, 192},
	{128, 128, 128}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0},
	{0, 0, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255},
}

// palette256 returns 256 palette index for RGB color.
func palette256(c ColorSpec) int {
	best := 0
	bestD := -1
	for i := 0; i < 256; i++ {
		var rgb [3]int
		if i < 16 {
			rgb = ansiPalette[i]
		} else if i < 232 {
			n := i - 16
			rgb = [3]int{cubeLevels[n/36], cubeLevels[(n/6)%6], cubeLevels[n%6]}
		} else {
			v := 8 + (i-232)*10
			rgb = [3]int{v, v, v}
		}
		dr := c.R - rgb[0]
		dg := c.G - rgb[1]
		db := c.B - rgb[2]
		d := 2*dr*dr + 4*dg*dg + 3*db*db
		if bestD < 0 || d < bestD {
			bestD = d
			best = i
		}
	}
	return best
}

// Style is a cell style.
type Style struct {
	Fg, Bg    ColorSpec
	Bold      bool
	Dim       bool
	Underline bool
	Reverse   bool
}

func (s Style) fg(c ColorSpec) Style  { s.Fg = c; return s }
func (s Style) bg(c ColorSpec) Style  { s.Bg = c; return s }
func (s Style) bold() Style           { s.Bold = true; return s }

// StyleKey is a comparable representation of a style for diffing.
func (s Style) key() string {
	return fmt.Sprintf("%d,%d,%d,%d,%t,%t,%t,%t", s.Fg.Kind, s.Fg.Idx, s.Bg.Kind, s.Bg.Idx, s.Bold, s.Dim, s.Reverse, s.Underline)
}

func (s Style) isDefault() bool {
	return s.Fg.Kind == ColorDefault && s.Bg.Kind == ColorDefault && !s.Bold && !s.Dim && !s.Reverse && !s.Underline
}

// sequence returns the SGR sequence parts for the style, given depth.
func (s Style) sequence(depth int, last Style) string {
	var parts []string
	if last.Bold && !s.Bold {
		parts = append(parts, "22")
	}
	if last.Dim && !s.Dim {
		parts = append(parts, "22")
	}
	if last.Reverse && !s.Reverse {
		parts = append(parts, "27")
	}
	if last.Underline && !s.Underline {
		parts = append(parts, "24")
	}
	if s.Bold {
		parts = append(parts, "1")
	}
	if s.Dim {
		parts = append(parts, "2")
	}
	if s.Reverse {
		parts = append(parts, "7")
	}
	if s.Underline {
		parts = append(parts, "4")
	}
	if fg := colorSeq(s.Fg, last.Fg, depth, false); fg != "" {
		parts = append(parts, fg)
	}
	if bg := colorSeq(s.Bg, last.Bg, depth, true); bg != "" {
		parts = append(parts, bg)
	}
	return strings.Join(parts, ";")
}

func colorSeq(c, last ColorSpec, depth int, bg bool) string {
	if c.Kind == ColorDefault {
		if last.Kind == ColorDefault {
			return ""
		}
		if bg {
			return "49"
		}
		return "39"
	}
	off := 30
	if bg {
		off = 40
	}
	switch c.Kind {
	case ColorANSI:
		n := c.Idx
		if depth < 16 {
			if n > 7 {
				return strconv.Itoa(off + 60 + n - 8)
			}
			return strconv.Itoa(off + n)
		}
		if depth == 16 {
			if n > 7 {
				return strconv.Itoa(off + 60 + n - 8)
			}
			return strconv.Itoa(off + n)
		}
		if bg {
			return "48;5;" + strconv.Itoa(n)
		}
		return "38;5;" + strconv.Itoa(n)
	case ColorIdx:
		if bg {
			return "48;5;" + strconv.Itoa(c.Idx)
		}
		return "38;5;" + strconv.Itoa(c.Idx)
	case ColorRGB:
		switch depth {
		case 24:
			if bg {
				return fmt.Sprintf("48;2;%d;%d;%d", c.R, c.G, c.B)
			}
			return fmt.Sprintf("38;2;%d;%d;%d", c.R, c.G, c.B)
		case 256:
			n := palette256(c)
			if bg {
				return "48;5;" + strconv.Itoa(n)
			}
			return "38;5;" + strconv.Itoa(n)
		default:
			n := ansiIndex(c)
			if n > 7 {
				return strconv.Itoa(off + 60 + n - 8)
			}
			return strconv.Itoa(off + n)
		}
	}
	return ""
}
GOEOF
