// Resize resizes the screen buffer.
func (s *Screen) Resize(rows, cols int) {
	if rows == s.rows && cols == s.cols {
		return
	}
	s.rows, s.cols = rows, cols
	s.alloc()
	s.invalid = true
}

func (s *Screen) Size() (int, int) { return s.rows, s.cols }

// Clear resets the buffer contents.
func (s *Screen) Clear() {
	for i := range s.cells {
		for j := range s.cells[i] {
			s.cells[i][j] = cell{r: ' ', st: Style{}}
		}
	}
}

// FillRow writes text starting at given column.
func (s *Screen) FillRow(y int, x int, text string, st Style) {
	if y < 0 || y >= s.rows {
		return
	}
	col := x
	for _, r := range text {
		if col >= s.cols {
			break
		}
		s.cells[y][col] = cell{r: r, st: st}
		col++
	}
}

// SetCell sets a single cell.
func (s *Screen) SetCell(x, y int, r rune, st Style) {
	if y < 0 || y >= s.rows || x < 0 || x >= s.cols {
		return
	}
	s.cells[y][x] = cell{r: r, st: st}
}

// GetString returns text of a row (for debugging).
func (s *Screen) GetString(y int) string {
	if y < 0 || y >= s.rows {
		return ""
	}
	var sb strings.Builder
	for _, c := range s.cells[y] {
		sb.WriteRune(c.r)
	}
	return strings.TrimRight(sb.String(), " ")
}

// Show flushes the difference to the terminal.
func (s *Screen) Show() {
	s.mtx.Lock()
	defer s.mtx.Unlock()
	var sb strings.Builder
	if s.invalid {
		sb.WriteString("\x1b[H\x1b[2J")
		s.invalid = false
		s.styleSet = false
		s.curStyle = Style{}
	}
	for y := 0; y < s.rows; y++ {
		rowChanged := false
		for x := 0; x < s.cols; x++ {
			if s.cells[y][x] != s.prev[y][x] {
				rowChanged = true
				break
			}
		}
		if !rowChanged {
			continue
		}
		needMove := true
		for x := 0; x < s.cols; x++ {
			c := s.cells[y][x]
			if c == s.prev[y][x] {
				continue
			}
			if needMove {
				sb.WriteString("\x1b[" + itoa(y+1) + ";" + itoa(x+1) + "H")
				s.cx, s.cy = x, y
				needMove = false
			} else if s.cx != x {
				sb.WriteString("\x1b[" + itoa(y+1) + ";" + itoa(x+1) + "H")
				s.cx, s.cy = x, y
			}
			if !s.styleSet || c.st.key() != s.curStyle.key() {
				sb.WriteString(styleSeq(c.st, s.curStyle, s.styleSet, s.depth))
				s.curStyle = c.st
				s.styleSet = true
			}
			sb.WriteRune(c.r)
			s.cx++
		}
	}
	if sb.Len() > 0 {
		io.WriteString(s.w, sb.String())
	}
	for y := 0; y < s.rows; y++ {
		copy(s.prev[y], s.cells[y])
	}
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	neg := v < 0
	if neg {
		v = -v
	}
	var b [20]byte
	i := len(b)
	for v > 0 {
		i--
		b[i] = byte('0' + v%10)
		v /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

// styleSeq produces SGR transition between two styles.
func styleSeq(n, last Style, haveLast bool, depth int) string {
	if haveLast && n.key() == last.key() {
		return ""
	}
	var sb strings.Builder
	needReset := false
	if haveLast {
		if last.Bold && !n.Bold {
			needReset = true
		}
		if last.Dim && !n.Dim {
			needReset = true
		}
		if last.Reverse && !n.Reverse {
			needReset = true
		}
		if last.Underline && !n.Underline {
			needReset = true
		}
	}
	if needReset {
		sb.WriteString("\x1b[0m")
	}
	if n.Bold {
		sb.WriteString("\x1b[1m")
	}
	if n.Dim {
		sb.WriteString("\x1b[2m")
	}
	if n.Reverse {
		sb.WriteString("\x1b[7m")
	}
	if n.Underline {
		sb.WriteString("\x1b[4m")
	}
	if !haveLast || n.Fg.key() != last.Fg.key() {
		if q := colorSeq(n.Fg, last.Fg, depth, false); q != "" {
			sb.WriteString("\x1b[" + q + "m")
		}
	}
	if !haveLast || n.Bg.key() != last.Bg.key() {
		if q := colorSeq(n.Bg, last.Bg, depth, true); q != "" {
			sb.WriteString("\x1b[" + q + "m")
		}
	}
	return sb.String()
}

// Init sends terminal initialization sequence.
func (s *Screen) Init() {
	io.WriteString(s.w, "\x1b[?1000l\x1b[?1002l\x1b[?1003l\x1b[?1006l\x1b[?2004l")
	io.WriteString(s.w, "\x1b[?1049h")
	io.WriteString(s.w, "\x1b[?25l")
	io.WriteString(s.w, "\x1b[H\x1b[2J")
	s.invalid = true
}

// Fini restores the terminal.
func (s *Screen) Fini() {
	io.WriteString(s.w, "\x1b[0m\x1b[39m\x1b[49m")
	io.WriteString(s.w, "\x1b[?25h")
	io.WriteString(s.w, "\x1b[?1049l")
}

// Sync writes synchronisation hints similar to what tcell does.
func (s *Screen) Sync() {
	io.WriteString(s.w, "\x1b[?2026h")
	s.Show()
	io.WriteString(s.w, "\x1b[?2026l")
}

// Terminal size helper used by UI.
func termDims() (int, int) {
	rows, cols, ok := termSize(os.Stdout.Fd())
	if !ok || rows <= 0 || cols <= 0 {
		rows, cols, ok = termSize(os.Stdin.Fd())
		if !ok {
			return 0, 0
		}
	}
	return rows, cols
}
GOEOF
