type KeyEv struct {
	Key Key
	R   rune
}

type keyReader struct {
	fd    uintptr
	buf   []byte
	pos   int
	n     int
	eof   bool
}

func newKeyReader() *keyReader {
	return &keyReader{fd: os.Stdin.Fd()}
}

func (k *keyReader) fill() bool {
	if k.pos < k.n {
		return true
	}
	if k.eof {
		return false
	}
	var buf [256]byte
	n, err := syscall.Read(int(k.fd), buf[:])
	if err != nil || n <= 0 {
		k.eof = true
		return false
	}
	k.buf = buf[:n]
	k.pos = 0
	k.n = n
	return true
}

func (k *keyReader) peekByte() (byte, bool) {
	if !k.fill() {
		return 0, false
	}
	return k.buf[k.pos], true
}

func (k *keyReader) nextByte() (byte, bool) {
	if !k.fill() {
		return 0, false
	}
	b := k.buf[k.pos]
	k.pos++
	return b, true
}

// waitReadable blocks until input is available or timeout (ms).
func (k *keyReader) waitReadable(ms int) bool {
	if k.pos < k.n {
		return true
	}
	if k.eof {
		return false
	}
	var set syscall.FdSet
	set.Bits[k.fd/64] |= 1 << (k.fd % 64)
	tv := syscall.Timeval{Sec: int64(ms / 1000), Usec: int64((ms % 1000) * 1000)}
	n, err := syscall.Select(int(k.fd)+1, &set, nil, nil, &tv)
	if err != nil {
		return false
	}
	return n > 0
}

// Next returns next key event, blocking if needed.
func (k *keyReader) Next(block bool) (KeyEv, bool) {
	for {
		b, ok := k.nextByte()
		if !ok {
			return KeyEv{}, false
		}
		if b != 0x1b {
			return decodeSingle(b)
		}
		// escape sequence
		nb, ok2 := k.nextByte()
		if !ok2 {
			return KeyEv{Key: KeyEsc}, true
		}
		switch nb {
		case '[':
			return k.readCSI()
