func decodeSingle(b byte) (KeyEv, bool) {
	switch b {
	case 0x0d, 0x0a:
		return KeyEv{Key: KeyEnter}, true
	case 0x09:
		return KeyEv{Key: KeyTab}, true
	case 0x7f, 0x08:
		return KeyEv{Key: KeyBS}, true
	case 0x01:
