func decodeRune(b byte) (rune, size int) {
	switch {
	case b < 0x80:
		return rune(b), 1
	}
	// handled by caller
	return rune(b), 1
}

func (k *keyReader) readCSI() (KeyEv, bool) {
	var params []byte
	for {
		c, ok := k.nextByte()
		if !ok {
