			case "2":
				return KeyEv{Key: KeyOther}, true
			case "3":
				return KeyEv{Key: KeyDel}, true
			case "4", "8":
				return KeyEv{Key: KeyEnd}, true
			case "5":
				return KeyEv{Key: KeyPgUp}, true
			case "6":
				return KeyEv{Key: KeyPgDn}, true
			}
			return KeyEv{Key: KeyOther}, true
		}
		return KeyEv{Key: KeyOther}, true
	}
}

// getWinsize returns the terminal size via ioctl.
func getWinsize(fd uintptr) (int, int) {
	var ws winsize
	if err := ioctl(fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws))); err != nil {
		return 0, 0
	}
	return int(ws.Row), int(ws.Col)
}
