		return KeyEv{Key: KeyEnter}, true
	case 0x09:
		return KeyEv{Key: KeyTab}, true
	case 0x7f, 0x08:
		return KeyEv{Key: KeyBS}, true
	case 0x01:
		return KeyEv{Key: KeyCtrlA}, true
	case 0x03:
		return KeyEv{Key: KeyCtrlC}, true
	case 0x04:
		return KeyEv{Key: KeyCtrlD}, true
	case 0x05:
		return KeyEv{Key: KeyCtrlE}, true
	case 0x06:
		return KeyEv{Key: KeyCtrlF}, true
	case 0x0b:
		return KeyEv{Key: KeyCtrlK}, true
	case 0x0c:
		return KeyEv{Key: KeyCtrlL}, true
	case 0x15:
		return KeyEv{Key: KeyCtrlU}, true
	case 0x17:
		return KeyEv{Key: KeyCtrlW}, true
	case 0x1b:
		return KeyEv{Key: KeyEsc}, true
	}
	if b < 0x20 {
		return KeyEv{Key: KeyOther, R: rune(b)}, true
	}
	// utf8
	r, size := decodeRune(b)
	if size == 1 {
		return KeyEv{Key: KeyRune, R: r}, true
	}
	return KeyEv{Key: KeyRune, R: r}, true
}

func decodeRune(b byte) (rune, size int) {
	switch {
	case b < 0x80:
		return rune(b), 1
	}
	// handled by caller
	return rune(b), 1
}

func (k *keyReader) readCSI() (KeyEv, bool) {
	var params []byte
	for {
		c, ok := k.nextByte()
		if !ok {
			return KeyEv{Key: KeyOther}, true
		}
		if c >= '0' && c <= '9' || c == ';' || c == '?' || c == '<' {
			params = append(params, c)
			continue
		}
		switch c {
		case 'A':
			return KeyEv{Key: KeyUp}, true
		case 'B':
			return KeyEv{Key: KeyDown}, true
		case 'C':
			return KeyEv{Key: KeyRight}, true
		case 'D':
			return KeyEv{Key: KeyLeft}, true
		case 'H':
			return KeyEv{Key: KeyHome}, true
		case 'F':
			return KeyEv{Key: KeyEnd}, true
		case 'R':
			return KeyEv{Key: KeyOther}, true
		case '~':
			switch string(params) {
			case "1", "7":
				return KeyEv{Key: KeyHome}, true
			case "2":
				return KeyEv{Key: KeyOther}, true
			case "3":
				return KeyEv{Key: KeyDel}, true
			case "4", "8":
				return KeyEv{Key: KeyEnd}, true
			case "5":
				return KeyEv{Key: KeyPgUp}, true
			case "6":
				return KeyEv{Key: KeyPgDn}, true
			}
			return KeyEv{Key: KeyOther}, true
		}
		return KeyEv{Key: KeyOther}, true
	}
}

// getWinsize returns the terminal size via ioctl.
func getWinsize(fd uintptr) (int, int) {
	var ws winsize
	if err := ioctl(fd, syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws))); err != nil {
		return 0, 0
	}
	return int(ws.Row), int(ws.Col)
}
