func (u *UI) barTotalStr() int64 { return 0 }

// Draw renders the whole screen.
func (u *UI) Draw() {
	rows, cols := u.scr.Size()
	u.scr.Clear()
	hdr := u.headerStyle()
	if !u.cfg.Style.Header.Hidden {
		txt := " gdu ~ Use arrow keys to navigate, press ? for help"
		u.scr.FillRow(0, 0, txt, hdr)
		for x := len(txt); x < cols; x++ {
			u.scr.SetCell(x, 0, ' ', hdr)
		}
	}
	// second line: current path
	title := u.titleText()
	u.scr.FillRow(1, 0, title, Style{Bold: true})

	if u.dialog == "view" {
		u.drawFileView()
	} else if u.dialog == "disks" {
		u.drawDisks()
	} else {
		u.drawListing(rows, cols)
	}
	if u.dialog != "" {
		u.drawDialog()
	}
	if u.quitMsg != "" {
		u.scr.FillRow(rows-1, 0, u.quitMsg, u.footerStyle())
	} else if u.searchActive {
		u.scr.FillRow(rows-1, 0, "/"+u.searchText, u.footerStyle())
	} else {
		u.drawStatus(rows-1, cols)
	}
}

func (u *UI) titleText() string {
	if u.dialog == "view" && u.viewFile != nil {
		return " --- " + u.curPath + "/" + u.viewFile.Name + " ---"
	}
	return " --- " + u.curPath + " ---"
}

func (u *UI) drawListing(rows, cols int) {
	items := u.fullItems()
	visible := rows - 3
	if u.cfg.Style.Header.Hidden {
		visible = rows - 2
	}
	if visible < 0 {
		visible = 0
	}
	if len(items) == 0 {
		return
	}
	if u.sel >= len(items) {
		u.sel = len(items) - 1
	}
	if u.sel < 0 {
		u.sel = 0
	}
	if u.off > u.sel {
		u.off = u.sel
	}
	if u.sel >= u.off+visible {
		u.off = u.sel - visible + 1
	}
	if u.off < 0 {
		u.off = 0
	}
	// compute name column width
	maxName := 0
	for _, it := range items {
		n := len(it.Name)
		if it.IsDir {
			n++
		}
		if n > maxName {
			maxName = n
		}
	}
	extra := 0
	for _, it := range items {
		if u.marked[it] {
			extra = 2
			break
		}
	}
	nameW := maxName + 1 + extra
	barW := 11
	if u.cfg.Style.UseOldSizeBar {
		barW = 12
	}
	base := 2
	if u.cfg.Style.Header.Hidden {
		base = 1
	}
	barTotal := u.barTotal(items)
	for i := 0; i < visible; i++ {
		idx := u.off + i
		if idx >= len(items) {
			break
		}
		it := items[idx]
		y := base + i
		selected := idx == u.sel
		u.drawItemRow(y, it, selected, barTotal, nameW, barW)
	}
}

func (u *UI) drawItemRow(y int, it *Item, selected bool, barTotal int64, nameW, barW int) {
	_, cols := u.scr.Size()
	numSt := u.numberStyle()
	dirSt := u.dirNameStyle()
	base := 2
	if u.cfg.Style.Header.Hidden {
		base = 1
	}
	if selected {
		st := u.selectedStyle()
		// fill the whole row with the selected style later
		var sb strings.Builder
		flag := " "
		if it.Flag != 0 {
			flag = string(it.Flag)
		}
		sb.WriteString(flag)
		sizeStr := HumanSize(u.apparentSize(it), SizeOpts{})
		if it.Name == ".." {
			sizeStr = ""
		}
		for i := len(sizeStr); i < 10; i++ {
			sb.WriteString(" ")
		}
		sb.WriteString(sizeStr)
		sb.WriteString(" ")
		if u.cfg.Style.UseOldSizeBar {
			sb.WriteString(barCharsOld(u.apparentSize(it), barTotal))
		} else {
			sb.WriteString(barChars(u.apparentSize(it), barTotal))
		}
		if u.showCount {
			sb.WriteString(fmt.Sprintf("%6s", countStr(it)))
			sb.WriteString(" ")
		}
		if u.showMtime {
			sb.WriteString(formatMtime(it.Mtime))
			sb.WriteString(" ")
		}
		nm := it.Name
		if it.IsDir {
			nm = "/" + nm
		}
		if u.marked[it] {
			nm = "✓ " + nm
		} else if extraMarked(u) {
			nm = "  " + nm
		}
		sb.WriteString(nm)
		line := sb.String()
		u.scr.FillRow(y, 0, line, st)
		for x := len(line); x < cols; x++ {
			u.scr.SetCell(x, y, ' ', st)
		}
		return
	}
	// non selected: flag column default, size colored, bar default, name colored for dirs
	flag := " "
	if it.Flag != 0 {
		flag = string(it.Flag)
	}
	u.scr.SetCell(0, y, rune(flag[0]), Style{})
	sizeStr := HumanSize(u.apparentSize(it), SizeOpts{})
	if it.Name == ".." {
		sizeStr = ""
	}
	pad := 10 - len(sizeStr)
	if pad < 0 {
		pad = 0
	}
	x := 1
	for i := 0; i < pad; i++ {
		u.scr.SetCell(x, y, ' ', Style{})
		x++
	}
	num, unit := splitHumanSize(u.apparentSize(it), SizeOpts{})
	if it.Name != ".." {
		for _, r := range num {
			u.scr.SetCell(x, y, r, numSt)
			x++
		}
	} else {
		x += len(num)
	}
	if unit != "" {
		for _, r := range " " + unit {
			u.scr.SetCell(x, y, r, Style{})
			x++
		}
	}
	// space
	u.scr.SetCell(x, y, ' ', Style{})
	x++
	// bar
	if u.cfg.Style.UseOldSizeBar {
		for _, r := range barCharsOld(u.apparentSize(it), barTotal) {
			u.scr.SetCell(x, y, r, Style{})
			x++
		}
	} else {
		bstr := barChars(u.apparentSize(it), barTotal)
		for i, r := range bstr {
			if i == len(bstr)-1 {
				u.scr.SetCell(x, y, r, Style{})
			} else {
				u.scr.SetCell(x, y, r, Style{})
			}
			x++
		}
	}
	if u.showCount {
		cs := fmt.Sprintf("%6s", countStr(it))
		for _, r := range cs {
			u.scr.SetCell(x, y, r, numSt)
			x++
		}
		u.scr.SetCell(x, y, ' ', Style{})
		x++
	}
	if u.showMtime {
		ms := formatMtime(it.Mtime) + " "
		for _, r := range ms {
			u.scr.SetCell(x, y, r, numSt)
			x++
		}
	}
	nm := it.Name
	if it.IsDir {
		nm = "/" + nm
	}
	if u.marked[it] {
		nm = "✓ " + nm
	} else if extraMarked(u) {
		nm = "  " + nm
	}
	st := Style{}
	if it.IsDir {
		st = dirSt
	}
	for _, r := range nm {
		u.scr.SetCell(x, y, r, st)
		x++
	}
	_ = nameW
}

func extraMarked(u *UI) bool {
	for _, it := range u.cur.Children {
		if u.marked[it] {
			return true
		}
	}
	return false
}

func countStr(it *Item) string {
	if it.Name == ".." {
		return ""
	}
	return fmt.Sprintf("%d", it.Count())
}

func (u *UI) drawStatus(y, cols int) {
	st := u.footerStyle()
	numSt := u.footerNumberStyle()
	items := u.currentItems()
	if len(items) == 0 && len(u.marked) == 0 {
		txt := " No items to display. "
		u.scr.FillRow(y, 0, txt, st)
		for x := len(txt); x < cols; x++ {
			u.scr.SetCell(x, y, ' ', st)
		}
		return
	}
	var sb []struct {
		text string
		num  string
		st   Style
	}
	parts := []struct {
		pre   string
		val   string
	}{
		{" Total disk usage: ", HumanSize(u.totalDisk(), SizeOpts{})},
		{" Apparent size: ", HumanSize(u.totalApp(), SizeOpts{})},
		{" Items: ", fmt.Sprintf("%d", u.itemCount())},
		{" Sorting by: ", u.sortKey + " " + sortName(u.sortAsc)},
	}
	line := ""
	if len(u.marked) > 0 {
		line += fmt.Sprintf(" Selected items: %d ", len(u.marked))
	}
	_ = sb
	full := line
	for _, p := range parts {
		full += p.pre + p.val
	}
	// simple approach: draw whole line in footer style, numbers in number style
	x := 0
	if line != "" {
		for _, r := range line {
			u.scr.SetCell(x, y, r, st)
			x++
		}
	}
	for _, p := range parts {
		for _, r := range p.pre {
			u.scr.SetCell(x, y, r, st)
			x++
		}
		for _, r := range p.val {
			u.scr.SetCell(x, y, r, numSt)
			x++
		}
	}
	for x < cols {
		u.scr.SetCell(x, y, ' ', st)
		x++
	}
}

func sortName(asc bool) string {
	if asc {
		return "asc"
	}
	return "desc"
}

// Run executes the interactive loop.
func (u *UI) Run() {
	kr := newKeyReader()
	// show scanning dialog while scanning is in progress is handled by caller
	u.scr.Sync()
	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	resize := false
	for {
		u.Draw()
		u.scr.Sync()
		// handle pending input
		handled := false
		for {
			if !kr.waitReadable(0) {
				break
			}
			ev, ok := kr.Next(true)
			if !ok {
				return
			}
			if u.handleKey(ev) {
				return
			}
			handled = true
		}
		if !handled {
			// wait for input or tick
			for {
				if kr.waitReadable(50) {
					break
				}
				rows, cols := getWinsize(os.Stdout.Fd())
				if rows != u.scr.rows || cols != u.scr.cols {
					if rows > 0 && cols > 0 {
						u.scr.Resize(rows, cols)
						resize = true
					}
				}
				select {
				case <-ticker.C:
					// periodic redraw (rescan progress etc.)
				default:
				}
			}
			_ = resize
		}
	}
}

func (u *UI) handleKey(ev KeyEv) bool {
	if u.dialog == "help" {
		if ev.Key == KeyEsc || ev.R == 'q' || ev.R == 'Q' || ev.Key == KeyEnter {
			u.dialog = ""
			return false
		}
		return false
	}
	if u.dialog == "info" {
		if ev.Key == KeyEsc || ev.R == 'q' || ev.Key == KeyEnter {
			u.dialog = ""
			return false
		}
		return false
	}
	if u.dialog == "delete" {
		return u.handleDeleteKey(ev)
	}
	if u.dialog == "export" {
		return u.handleExportKey(ev)
	}
	if u.dialog == "view" {
		switch ev.Key {
		case KeyEsc:
			u.dialog = ""
			u.viewFile = nil
			return false
		case KeyRune:
			if ev.R == 'q' || ev.R == 'Q' {
				u.dialog = ""
				u.viewFile = nil
				return false
			}
			if ev.R == 'j' {
				u.viewOff++
			} else if ev.R == 'k' {
				if u.viewOff > 0 {
					u.viewOff--
				}
			}
		case KeyDown:
			u.viewOff++
		case KeyUp:
			if u.viewOff > 0 {
				u.viewOff--
			}
		case KeyPgDn:
			rows, _ := u.scr.Size()
			u.viewOff += rows - 3
		case KeyPgUp:
			rows, _ := u.scr.Size()
			u.viewOff -= rows - 3
			if u.viewOff < 0 {
				u.viewOff = 0
			}
		}
		return false
	}
	if u.dialog == "disks" {
		if ev.Key == KeyEsc || ev.R == 'q' || ev.Key == KeyEnter {
			u.dialog = ""
			return false
		}
		return false
	}
	if u.searchActive {
		switch ev.Key {
		case KeyEsc:
			u.searchActive = false
			u.searchText = ""
		case KeyEnter:
			u.searchActive = false
		case KeyBS:
			if len(u.searchText) > 0 {
				r := []rune(u.searchText)
				u.searchText = string(r[:len(r)-1])
			}
		case KeyRune:
			u.searchText += string(ev.R)
		}
		return false
	}
	switch ev.Key {
	case KeyUp:
		u.move(-1)
	case KeyDown:
		u.move(1)
	case KeyLeft:
		u.goParent()
	case KeyRight, KeyEnter:
		u.goInto()
	case KeyPgUp:
		rows, _ := u.scr.Size()
		u.move(-(rows - 3))
	case KeyPgDn:
		rows, _ := u.scr.Size()
		u.move(rows - 3)
	case KeyCtrlC:
		return true
	case KeyRune:
		return u.handleRune(ev.R)
	}
	return false
}

func (u *UI) handleRune(r rune) bool {
	items := u.fullItems()
	switch r {
	case 'q':
		return true
	case 'Q':
		u.quitMsg = u.curPath
		return true
	case '?':
		u.dialog = "help"
	case 'j':
		u.move(1)
	case 'k':
		u.move(-1)
	case 'h':
		u.goParent()
	case 'l':
		u.goInto()
	case 'g':
		u.sel = 0
		u.off = 0
	case 'G':
		u.sel = len(items) - 1
	case 'a':
		u.apparent = !u.apparent
	case 'B':
		u.barBig = !u.barBig
	case 'c':
		u.showCount = !u.showCount
	case 'm':
		u.showMtime = !u.showMtime
	case 'n':
		u.setSort("name")
	case 's':
		u.setSort("size")
	case 'C':
		u.setSort("itemCount")
	case 'M':
		u.setSort("mtime")
	case ' ':
		if u.sel < len(items) {
			it := items[u.sel]
			if u.marked[it] {
				delete(u.marked, it)
			} else {
				u.marked[it] = true
			}
		}
	case 'I':
		if u.sel < len(items) {
			it := items[u.sel]
			if u.ignored[it] {
				delete(u.ignored, it)
			} else {
				u.ignored[it] = true
			}
		}
	case 'i':
		if u.sel < len(items) {
			it := items[u.sel]
			if it.Name == ".." {
				u.infoItem = u.cur
			} else {
				u.infoItem = it
			}
			u.dialog = "info"
		}
	case 'd':
		if u.cfg.NoDelete {
			return false
		}
		if u.sel < len(items) {
			it := items[u.sel]
			if it.Name == ".." {
				return false
			}
			u.deleteItem = it
			u.deleteOpt = 0
			u.dialog = "delete"
		}
	case 'e':
		if u.sel < len(items) {
			it := items[u.sel]
			if it.IsDir && it.Name != ".." {
				u.emptyDir(it)
			}
		}
	case 'v':
		if u.sel < len(items) {
			it := items[u.sel]
			if !it.IsDir {
				u.viewFile = it
				u.viewOff = 0
				u.loadFileContent()
				u.dialog = "view"
			}
		}
	case 'r':
		u.rescan()
	case 'E':
		u.exportName = "export.json"
		u.exportField = 0
		u.dialog = "export"
	case '/':
		u.searchActive = true
		u.searchText = ""
	case 'b':
		u.spawnShell()
	case 'o':
		if u.sel < len(items) {
			u.openItem(items[u.sel])
		}
	}
	return false
}

func (u *UI) setSort(key string) {
	if u.sortKey == key {
		u.sortAsc = !u.sortAsc
	} else {
		u.sortKey = key
		u.sortAsc = true
	}
}

func (u *UI) move(d int) {
	items := u.fullItems()
	if len(items) == 0 {
		return
	}
	u.sel += d
	if u.sel < 0 {
		u.sel = 0
	}
	if u.sel >= len(items) {
		u.sel = len(items) - 1
	}
}

func (u *UI) goParent() {
	if u.cur == u.root {
		return
	}
	parent := u.findParent(u.root, u.cur)
	if parent == nil {
		return
	}
	u.cur = parent
	u.curPath = filepath.Dir(u.curPath)
	if u.curPath == "." {
		u.curPath = "/"
	}
	u.sel = 0
	u.off = 0
}

func (u *UI) findParent(root, target *Item) *Item {
	if root == target {
		return nil
	}
	for _, c := range root.Children {
		if c == target {
			return root
		}
		if c.IsDir {
			if p := u.findParent(c, target); p != nil {
				return p
			}
		}
	}
	return nil
}

func (u *UI) goInto() {
	items := u.fullItems()
	if u.sel >= len(items) {
		return
	}
	it := items[u.sel]
	if !it.IsDir {
		return
	}
	if it.Name == ".." {
		u.goParent()
		return
	}
	u.cur = it
	if u.curPath == "/" {
		u.curPath = "/" + it.Name
	} else {
		u.curPath = u.curPath + "/" + it.Name
	}
	u.sel = 0
	u.off = 0
}

func (u *UI) rescan() {
	opts := u.cfg.scanOpts()
	st := &Stats{Start: time.Now()}
	item, err := Scan(u.curPath, opts, st)
	if err != nil {
		return
	}
	// replace in parent
	if u.cur == u.root {
		u.root = item
		u.cur = item
	} else {
		parent := u.findParent(u.root, u.cur)
		if parent != nil {
			for i, c := range parent.Children {
				if c == u.cur {
					parent.Children[i] = item
					break
				}
			}
		}
		u.cur = item
	}
	recomputeSizes(u.root)
}

func (u *UI) emptyDir(it *Item) {
	path := u.curPath + "/" + it.Name
	entries, err := os.ReadDir(path)
	if err != nil {
		return
	}
	for _, e := range entries {
		os.RemoveAll(path + "/" + e.Name())
	}
	u.rescan()
}

func (u *UI) spawnShell() {
	if u.cfg.NoSpawnShell {
		return
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}
	cmd := exec.Command(shell)
	cmd.Dir = u.curPath
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	u.scr.Fini()
	st, _ := makeRaw(os.Stdin.Fd())
	restoreTerm(st)
	if err := cmd.Run(); err != nil {
	}
	st2, _ := makeRaw(os.Stdin.Fd())
	_ = st2
	u.scr.Init()
}

func (u *UI) openItem(it *Item) {
	path := u.curPath + "/" + it.Name
	if it.IsDir {
		path = u.curPath + "/" + it.Name
	}
	var cmd *exec.Cmd
	if it.IsDir {
		cmd = exec.Command("xdg-open", path)
	} else {
		cmd = exec.Command("xdg-open", path)
	}
	if err := cmd.Start(); err == nil {
		cmd.Process.Release()
	}
}

func (u *UI) loadFileContent() {
	if u.viewFile == nil {
		return
	}
	data, err := os.ReadFile(u.curPath + "/" + u.viewFile.Name)
	if err != nil {
		u.viewLines = []string{"error: " + err.Error()}
		return
	}
	s := strings.ReplaceAll(string(data), "\r\n", "\n")
	u.viewLines = strings.Split(s, "\n")
}

func (u *UI) drawFileView() {
	rows, cols := u.scr.Size()
	base := 2
	if u.cfg.Style.Header.Hidden {
		base = 1
	}
	for i := 0; i < rows-base-1; i++ {
		idx := u.viewOff + i
		if idx >= len(u.viewLines) {
			break
		}
		line := u.viewLines[idx]
		if len(line) > cols {
			line = line[:cols]
		}
		u.scr.FillRow(base+i, 0, line, Style{})
	}
}

func (u *UI) drawDisks() {
	rows, cols := u.scr.Size()
	base := 2
	disks := MountedDisks()
	hdr := "Device name  Size    Used    Used part    Free    Mount point"
	u.scr.FillRow(base, 0, hdr, Style{Bold: false})
	u.scr.SetCell(0, base, 'D', Style{Bold: false})
	for i, d := range disks {
		y := base + 1 + i
		if y >= rows-1 {
			break
		}
		used := d.Used
		var total int64
		for _, dd := range disks {
			if dd.Device == d.Device {
				total += dd.Total
			}
		}
		line := fmt.Sprintf("%-12s %-7s %-7s ", d.Device, HumanSize(d.Total, SizeOpts{}), HumanSize(used, SizeOpts{}))
		line += barChars(used, total) + " " + HumanSize(d.Free, SizeOpts{}) + " " + d.MountPoint
		u.scr.FillRow(y, 0, line, Style{})
	}
}

func (u *UI) handleDeleteKey(ev KeyEv) bool {
	switch ev.Key {
	case KeyEsc:
		u.dialog = ""
		return false
	case KeyLeft:
		if u.deleteOpt > 0 {
			u.deleteOpt--
		}
	case KeyRight:
		if u.deleteOpt < 2 {
			u.deleteOpt++
		}
	case KeyRune:
		switch ev.R {
		case 'q', 'Q':
			u.dialog = ""
		case 'y':
			u.doDelete()
		case 'n':
			u.dialog = ""
		}
	case KeyEnter:
		if u.deleteOpt == 1 {
			u.doDelete()
		} else {
			u.dialog = ""
		}
	}
	return false
}

func (u *UI) doDelete() {
	if u.deleteItem == nil {
		u.dialog = ""
		return
	}
	path := u.curPath + "/" + u.deleteItem.Name
	os.RemoveAll(path)
	u.dialog = ""
	u.rescan()
}

func (u *UI) handleExportKey(ev KeyEv) bool {
	switch ev.Key {
	case KeyEsc:
		u.dialog = ""
		return false
	case KeyBS:
		if len(u.exportName) > 0 {
			r := []rune(u.exportName)
			u.exportName = string(r[:len(r)-1])
		}
	case KeyRune:
		u.exportName += string(ev.R)
	case KeyEnter:
		path := u.exportName
		if !filepath.IsAbs(path) {
			path = filepath.Join(u.curPath, path)
		}
		exportJSON(path, u.root, time.Now().Unix())
		u.dialog = ""
	}
	return false
}

func (u *UI) drawDialog() {
	switch u.dialog {
	case "help":
		drawHelpDialog(u)
	case "info":
		drawInfoDialog(u)
	case "delete":
		drawDeleteDialog(u)
	case "export":
		drawExportDialog(u)
	}
}
