}

func (b *dialogBox) draw(s *Screen, borderStyle, titleStyle Style) {
	var tl, tr, bl, br, hz, vt rune
	if b.kind == boxDouble {
		tl, tr, bl, br, hz, vt = '╔', '╗', '╚', '╝', '═', '║'
	} else {
		tl, tr, bl, br, hz, vt = '┌', '┐', '└', '┘', '─', '│'
	}
	// top
	s.SetCell(b.x, b.y, tl, borderStyle)
	s.SetCell(b.x+b.w-1, b.y, tr, borderStyle)
	for x := b.x + 1; x < b.x+b.w-1; x++ {
		s.SetCell(x, b.y, hz, borderStyle)
	}
	if b.title != "" {
		t := " " + b.title + " "
		start := b.x + (b.w-len(t))/2
		for i, r := range t {
			s.SetCell(start+i, b.y, r, titleStyle)
		}
	}
	// bottom
	s.SetCell(b.x, b.y+b.h-1, bl, borderStyle)
	s.SetCell(b.x+b.w-1, b.y+b.h-1, br, borderStyle)
	for x := b.x + 1; x < b.x+b.w-1; x++ {
		s.SetCell(x, b.y+b.h-1, hz, borderStyle)
	}
	// sides
	for y := b.y + 1; y < b.y+b.h-1; y++ {
		s.SetCell(b.x, y, vt, borderStyle)
		s.SetCell(b.x+b.w-1, y, vt, borderStyle)
	}
}

func (b *dialogBox) innerW() int { return b.w - 2 }

// put writes text into the box content area with given offset.
func (b *dialogBox) put(s *Screen, row int, text string, st Style) {
	y := b.y + 1 + row
	x := b.x + 1
	for i, r := range text {
		if x+i >= b.x+b.w-1 {
			break
		}
		s.SetCell(x+i, y, r, st)
	}
}

func helpLines() []string {
	return []string{
		"",
		"",
		keyLine("up/down, k/j", "Move cursor up/down"),
		keyLine("pgup/pgdn, g/G", "Move cursor top/bottom"),
