		"",
		"",
	}
}

func keyLine(key, desc string) string {
	return fmt.Sprintf("%21s%s", key, desc)
}

const helpDialogWidth = 80

func drawHelpDialog(u *UI) {
	rows, cols := u.scr.Size()
	lines := helpLines()
	h := len(lines) + 2
	if h > rows {
		h = rows
		lines = lines[:rows-4]
		lines = append(lines, "", "")
	}
	y := (rows - h) / 2
	if y < 0 {
		y = 0
	}
	x := (cols - helpDialogWidth) / 2
	b := u.box(x, y, helpDialogWidth, h, boxDouble, "gdu help")
	b.draw(u.scr, Style{}, Style{}.fg(ParseColor("#1BA1E7")))
	st := Style{}.fg(ColorSpec{Kind: ColorANSI, Idx: 15})
	keySt := Style{}.fg(ColorSpec{Kind: ColorANSI, Idx: 9})
	for i, l := range lines {
		if i >= h-2 {
			break
		}
		if i > 5 && l != "" && !strings.HasPrefix(l, "  ") {
			// section header
			b.put(u.scr, i, "  "+l, st)
			continue
		}
		if l == "" {
			b.put(u.scr, i, "", st)
			continue
		}
		// split key/description
		key := strings.TrimLeft(l[:21], " ")
		desc := l[21:]
		b.put(u.scr, i, "  "+fmt.Sprintf("%21s", key)+desc, st)
		// recolor key
		start := b.x + 1 + 2
		for j := 0; j < 21; j++ {
			if j >= 21-len(key) {
				u.scr.SetCell(start+j, b.y+1+i, rune(key[j-(21-len(key))]), keySt)
			}
		}
	}
}

const infoDialogWidth = 80

func drawInfoDialog(u *UI) {
	rows, cols := u.scr.Size()
	it := u.infoItem
	var lines []string
	if it != nil {
		name := it.Name
		path := u.curPath
		if it.Name == ".." {
			name = filepathBase(u.curPath)
		} else if u.cur != u.root {
			path = u.curPath + "/" + it.Name
		} else {
			path = u.curPath + "/" + it.Name
		}
		typ := "File"
		if it.IsDir {
			typ = "Directory"
		}
		lines = []string{
			"",
			"",
			"  Name: " + name,
			"  Path: " + path,
			"  Type: " + typ,
			"",
			fmt.Sprintf("%15s: %s (%d B)", "Disk usage", HumanSize(it.Dsize, SizeOpts{}), it.Dsize),
			fmt.Sprintf("%15s: %s (%d B)", "Apparent size", HumanSize(it.Asize, SizeOpts{}), it.Asize),
			"",
