		}
	}
	h := len(lines) + 2
	y := (rows - h) / 2
	if y < 0 {
		y = 0
	}
	x := (cols - infoDialogWidth) / 2
	b := u.box(x, y, infoDialogWidth, h, boxSingle, "Item info")
	b.draw(u.scr, Style{}, Style{}.fg(ParseColor("#1BA1E7")))
	st := Style{}.fg(ColorSpec{Kind: ColorANSI, Idx: 15})
	for i, l := range lines {
		b.put(u.scr, i, "  "+l, st)
	}
}

func filepathBase(p string) string {
	i := strings.LastIndexByte(p, '/')
	if i < 0 {
		return p
	}
	return p[i+1:]
}

func deleteDialogWidth(w int) int {
	v := w * 35 / 100
	if v < 43 {
		v = 43
	}
	return v
}

func drawDeleteDialog(u *UI) {
	rows, cols := u.scr.Size()
	it := u.deleteItem
	if it == nil {
		return
	}
	w := deleteDialogWidth(cols)
	name := it.Name
	text := fmt.Sprintf("Are you sure you want to delete %q?", name)
	inner := w - 2
	opts := "no     yes     don't ask me again"
	lines := []string{
		center(text, inner),
		"",
		center(opts, inner),
		"",
	}
	h := len(lines) + 4
	y := (rows - h) / 2
	if y < 0 {
		y = 0
	}
	x := (cols - w) / 2
	b := u.box(x, y, w, h, boxDouble, "")
	b.draw(u.scr, Style{}, Style{})
	st := Style{}.fg(ColorSpec{Kind: ColorANSI, Idx: 15})
	b.put(u.scr, 0, "", st)
	b.put(u.scr, 1, center(text, inner), st)
	b.put(u.scr, 2, "", st)
	b.put(u.scr, 3, center(opts, inner), st)
	b.put(u.scr, 4, "", st)
}

func center(s string, w int) string {
	if len(s) >= w {
		return s
	}
	left := (w - len(s)) / 2
	return strings.Repeat(" ", left) + s
}

func exportDialogWidth(w int) int {
	return 52
}

func drawExportDialog(u *UI) {
	rows, cols := u.scr.Size()
	w := exportDialogWidth(cols)
	inner := w - 2
	lines := []string{
		" File name " + u.exportName,
		"",
		fmt.Sprintf("%*s", inner-6, "Export"),
		"",
	}
	h := len(lines) + 4
	y := (rows - h) / 2
	if y < 0 {
		y = 0
	}
	x := (cols - w) / 2
	b := u.box(x, y, w, h, boxDouble, "")
	b.draw(u.scr, Style{}, Style{})
	st := Style{}.fg(ColorSpec{Kind: ColorANSI, Idx: 15})
	b.put(u.scr, 0, "", st)
	b.put(u.scr, 1, " File name "+u.exportName, st)
	b.put(u.scr, 2, "", st)
	b.put(u.scr, 3, fmt.Sprintf("%*s", inner-6, "Export"), st)
	b.put(u.scr, 4, "", st)
}

// drawScanningDialog renders progress modal used during initial scan.
func drawScanningDialog(u *UI, s *Screen, rows, cols int, items int64, bytes int64, curItem string, elapsed string) {
	w := scanDialogWidth(cols)
	h := 8
	y := (rows - h) / 2
	if y < 0 {
		y = 0
	}
	x := (cols - w) / 2
	if x < 0 {
		x = 0
	}
	b := &dialogBox{x: x, y: y, w: w, h: h, kind: boxSingle, title: "Scanning..."}
	b.draw(s, Style{}, Style{}.fg(ParseColor("#1BA1E7")))
	st := Style{}.fg(ColorSpec{Kind: ColorANSI, Idx: 15})
	numSt := st
	b.put(s, 1, "", st)
	if curItem == "" {
		b.put(s, 2, "  Scanning...", st)
	} else {
		b.put(s, 1, fmt.Sprintf("  Total items: %s, size: %s, elapsed time: %s",
			commaInt(items), HumanSize(bytes, SizeOpts{}), elapsed), st)
		b.put(s, 2, "  Current item: "+curItem, st)
	}
	_ = numSt
}

func scanDialogWidth(w int) int {
	if w <= 53 {
		v := w - 1
		if v > 50 {
			v = 50
		}
		return v
	}
	d := w - 53
	q := d / 52
	r := d % 52
	add := r
	if add > 50 {
		add = 50
	}
	return 50 + 50*q + add
}
