package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type flagKind int

const (
	fBool flagKind = iota
	fString
	fInt
	fStrings
)

type flagDef struct {
	name   string
	short  string
	kind   flagKind
	desc   string
	strVal *string
	intVal *int
	boolVal *bool
	strsVal *[]string
}

func (f *flagDef) typeName() string {
	switch f.kind {
	case fString:
		return "string"
	case fInt:
		return "int"
	case fStrings:
		return "strings"
	}
	return ""
}

func (f *flagDef) displayName() string {
	if f.short != "" {
		return "-" + f.short + ", --" + f.name
	}
	return "--" + f.name
}

type flagSet struct {
	defs   []*flagDef
	byName map[string]*flagDef
	byShort map[string]*flagDef
	args   []string
	changed map[string]bool
}

func newFlagSet() *flagSet {
	return &flagSet{byName: map[string]*flagDef{}, byShort: map[string]*flagDef{}, changed: map[string]bool{}}
}

func (fs *flagSet) addBool(name, short, desc string, dst *bool) {
	d := &flagDef{name: name, short: short, kind: fBool, desc: desc, boolVal: dst}
	fs.defs = append(fs.defs, d)
	fs.byName[name] = d
	if short != "" {
		fs.byShort[short] = d
	}
