				if err := fs.setValue(f, args[i]); err != nil {
					return err
				}
				i++
			}
			continue
		}
		fs.args = append(fs.args, a)
	}
	return nil
}

func (fs *flagSet) usageErr(msg string) error {
	fmt.Fprintf(os.Stderr, "Error: %s\n", msg)
	os.Exit(1)
	return nil
}
