func mergeConfig(cfg, loaded *Config, fs *flagSet) {
	applyIfNotChanged := func(name string, fn func()) {
		if !fs.changed[name] {
			fn()
		}
	}
	applyIfNotChanged("log-file", func() { cfg.LogFile = loaded.LogFile })
	applyIfNotChanged("input-file", func() { cfg.InputFile = loaded.InputFile })
	applyIfNotChanged("output-file", func() { cfg.OutputFile = loaded.OutputFile })
	applyIfNotChanged("ignore-from-file", func() { cfg.IgnoreFromFile = loaded.IgnoreFromFile })
	applyIfNotChanged("db", func() { cfg.DB = loaded.DB })
	applyIfNotChanged("max-cores", func() { cfg.MaxCores = loaded.MaxCores })
	applyIfNotChanged("top", func() { cfg.Top = loaded.Top })
	applyIfNotChanged("depth", func() { cfg.Depth = loaded.Depth })
	applyIfNotChanged("ignore-dirs", func() { cfg.IgnoreDirs = loaded.IgnoreDirs })
	applyIfNotChanged("ignore-dirs-pattern", func() { cfg.ignoreDirPatternsFlag = loaded.ignoreDirPatternsFlag })
	applyIfNotChanged("type", func() { cfg.Type = loaded.Type })
	applyIfNotChanged("exclude-type", func() { cfg.ExcludeType = loaded.ExcludeType })
	bools := []struct {
		name string
		dst  *bool
	}{
		{"sequential", &cfg.SequentialScanning},
		{"show-apparent-size", &cfg.ShowApparentSize},
		{"show-relative-size", &cfg.ShowRelativeSize},
		{"show-annexed-size", &cfg.ShowAnnexedSize},
		{"show-item-count", &cfg.ShowItemCount},
		{"show-mtime", &cfg.ShowMtime},
		{"no-color", &cfg.NoColor},
		{"mouse", &cfg.Mouse},
		{"non-interactive", &cfg.NonInteractive},
		{"no-progress", &cfg.NoProgress},
		{"no-unicode", &cfg.NoUnicode},
		{"no-cross", &cfg.NoCross},
		{"no-hidden", &cfg.NoHidden},
		{"no-delete", &cfg.NoDelete},
		{"no-spawn-shell", &cfg.NoSpawnShell},
		{"follow-symlinks", &cfg.FollowSymlinks},
		{"profiling", &cfg.Profiling},
		{"read-from-storage", &cfg.ReadFromStorage},
		{"summarize", &cfg.Summarize},
		{"si", &cfg.UseSIPrefix},
		{"no-prefix", &cfg.NoPrefix},
		{"show-in-kib", &cfg.ShowInKib},
		{"reverse-sort", &cfg.ReverseSort},
		{"archive-browsing", &cfg.ArchiveBrowsing},
		{"collapse-path", &cfg.CollapsePath},
	}
	for _, b := range bools {
		nm := b.name
		applyIfNotChanged(nm, func() { *b.dst = cfgBool(loaded, nm) })
	}
	applyIfNotChanged("since", func() { cfg.Since = loaded.Since })
	applyIfNotChanged("until", func() { cfg.Until = loaded.Until })
	applyIfNotChanged("max-age", func() { cfg.MaxAge = loaded.MaxAge })
	applyIfNotChanged("min-age", func() { cfg.MinAge = loaded.MinAge })
	// style & sorting
	cfg.Style = loaded.Style
	cfg.SortBy = loaded.SortBy
	cfg.SortOrder = loaded.SortOrder
}

func cfgBool(c *Config, name string) bool {
	switch name {
	case "sequential":
		return c.SequentialScanning
	case "show-apparent-size":
		return c.ShowApparentSize
	case "show-relative-size":
		return c.ShowRelativeSize
	case "show-annexed-size":
		return c.ShowAnnexedSize
	case "show-item-count":
		return c.ShowItemCount
	case "show-mtime":
