	case "no-delete":
		return c.NoDelete
	case "no-spawn-shell":
		return c.NoSpawnShell
	case "follow-symlinks":
		return c.FollowSymlinks
	case "profiling":
		return c.Profiling
	case "read-from-storage":
		return c.ReadFromStorage
	case "summarize":
		return c.Summarize
	case "si":
		return c.UseSIPrefix
	case "no-prefix":
		return c.NoPrefix
	case "show-in-kib":
		return c.ShowInKib
	case "reverse-sort":
		return c.ReverseSort
	case "archive-browsing":
		return c.ArchiveBrowsing
	case "collapse-path":
		return c.CollapsePath
	}
