{"command": "cd /workspace && cat >> ui.go <<'GOEOF'

// runInteractive runs gdu in interactive (TUI) mode.
func runInteractive(cfg *Config, root *Item, rootPath string, opts *ScanOpts) {
	rows, cols := getWinsize(os.Stdout.Fd())
	if rows <= 0 || cols <= 0 {
		rows, cols = termDims()
	}
	scr := NewScreen(os.Stdout, rows, cols)
	scr.Init()
	defer scr.Fini()
	st, err := makeRaw(os.Stdin.Fd())
	if err == nil {
		defer restoreTerm(st)
	}
	// Show scanning dialog while scanning (already done, but mimic initial state)
	stats := &Stats{Start: time.Now()}
	stats.Items.Store(root.Count())
	stats.Bytes.Store(root.Dsize)
	u := NewUI(scr, cfg, root, rootPath)
	if lg := cfg.LogFile; lg != "" && lg != "/dev/null" {
		if f, e := os.OpenFile(lg, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644); e == nil {
			u.logFile = f
		}
	}
	// brief scanning dialog to mimic original behaviour
	drawScanningDialog(u, scr, rows, cols, stats.Items.Load(), stats.Bytes.Load(), rootPath, "0s")
	scr.Sync()
	time.Sleep(30 * time.Millisecond)
	u.Run()
}

// runNonInteractive produces non interactive output.
func runNonInteractive(cfg *Config, root *Item, rootName string, opts *ScanOpts, full string) {
	opts.Apparent = cfg.ShowApparentSize
	opts.SizeOpts = SizeOpts{SI: cfg.UseSIPrefix, Kib: cfg.ShowInKib, NoPrefix: cfg.NoPrefix}
	color := useColor(cfg)
	w := os.Stdout
	if cfg.OutputFile != "" {
		if err := exportJSON(cfg.OutputFile, root, time.Now().Unix()); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}
	if cfg.Summarize {
		p := &printer{w: w, color: color, opts: opts.SizeOpts, apparent: cfg.ShowApparentSize}
		sz := root.Dsize
		if cfg.ShowApparentSize {
			sz = root.Asize
		}
		s := p.sizeStr(sz)
		io.WriteString(w, p.pad(s, false)+s+" "+filepath.Base(rootName)+"\n")
		return
	}
	if cfg.Top > 0 {
		PrintTop(w, root, rootName, cfg.Top, color, opts.SizeOpts, cfg.ShowApparentSize)
		return
	}
	if cfg.Depth > 0 {
		PrintTree(w, root, rootName, cfg.Depth, color, opts.SizeOpts, cfg.ShowApparentSize)
		return
	}
	p := &printer{w: w, color: color, opts: opts.SizeOpts, apparent: cfg.ShowApparentSize}
	if cfg.ReverseSort {
		items := append([]*Item{}, root.Children...)
		SortBySizeDesc(items, cfg.ShowApparentSize)
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
		for _, it := range items {
			p.printItem(it, rootName, true)
		}
		return
	}
	p.printItems(root, rootName)
}
