// runNonInteractive produces non interactive output.
func runNonInteractive(cfg *Config, root *Item, rootName string, opts *ScanOpts, full string) {
	opts.Apparent = cfg.ShowApparentSize
	opts.SizeOpts = SizeOpts{SI: cfg.UseSIPrefix, Kib: cfg.ShowInKib, NoPrefix: cfg.NoPrefix}
	color := useColor(cfg)
	w := os.Stdout
	if cfg.OutputFile != "" {
		if err := exportJSON(cfg.OutputFile, root, time.Now().Unix()); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}
	if cfg.Summarize {
