	}
	if cfg.Depth > 0 {
		PrintTree(w, root, rootName, cfg.Depth, color, opts.SizeOpts, cfg.ShowApparentSize)
		return
	}
	p := &printer{w: w, color: color, opts: opts.SizeOpts, apparent: cfg.ShowApparentSize}
	if cfg.ReverseSort {
		items := append([]*Item{}, root.Children...)
		SortBySizeDesc(items, cfg.ShowApparentSize)
		for i, j := 0, len(items)-1; i < j; i, j = i+1, j-1 {
			items[i], items[j] = items[j], items[i]
		}
		for _, it := range items {
			p.printItem(it, rootName, true)
		}
		return
	}
	p.printItems(root, rootName)
}
